<script setup lang="ts">
/**
 * Anchor for a drawer-mode panel. Same role as `LayoutPanelSlot` —
 * registers its DOM element with the anchor registry so the
 * `LayoutManagerView` flat panel zone teleports content here. Differs
 * in two ways:
 *
 *   1. Positioning: absolutely positioned at the named edge of the
 *      parent layout container (left / right / bottom).
 *   2. Visibility: only "open" when the panel def's `drawerOpen` is
 *      true. A closed drawer keeps its full size and rests hidden at
 *      its edge, inside the layout, so it adds nothing to an ancestor's
 *      scrollable area. The panel content keeps its size across
 *      open/close, so no remount, no scroll loss, no iframe reload.
 *
 * Iframe-preservation across breakpoint flips is the key invariant.
 * When the same panel id appears in both an inline slot (default
 * breakpoint) and a drawer-mode slot (narrow breakpoint), the panel
 * id stays in `activePanelIds` across the flip, so the flat panel
 * zone keeps its component instance. The teleport target switches
 * from the inline `LayoutPanelSlot`'s element to this component's
 * element — Teleport re-targets reactively via the registry's
 * `reactive` map and Vue moves the existing DOM subtree without
 * re-running setup() or unmounting.
 */
import type { LayoutManager } from './layout-manager'
import type { PanelDisplay, PanelSlot } from './types'
import { computed, inject, onBeforeUnmount, ref, watch } from 'vue'
import { LAYOUT_ANCHOR_REGISTRY_KEY } from './composables'

const props = defineProps<{
  slotDef: PanelSlot
  manager: LayoutManager
}>()

const panelDef = computed(() => props.manager.getLayout().panels[props.slotDef.panel])
const drawerOpen = computed(() => Boolean(panelDef.value?.drawerOpen))

const anchorRegistry = inject(LAYOUT_ANCHOR_REGISTRY_KEY, null)
const anchorEl = ref<HTMLElement | null>(null)

watch(
  () => [anchorEl.value, props.slotDef.panel] as const,
  ([el, panelId], _old, onCleanup) => {
    if (!anchorRegistry || !el)
      return
    anchorRegistry[panelId] = el
    onCleanup(() => {
      if (anchorRegistry[panelId] === el)
        anchorRegistry[panelId] = null
    })
  },
  { immediate: true, flush: 'post' },
)

onBeforeUnmount(() => {
  if (!anchorRegistry)
    return
  const panelId = props.slotDef.panel
  if (anchorRegistry[panelId] === anchorEl.value)
    anchorRegistry[panelId] = null
})

/**
 * Default drawer dimensions per edge. Consumer overrides via
 * `slotDef.drawerSize`.
 */
const DEFAULT_W = '320px'
const DEFAULT_H = '320px'

const drawerStyle = computed<Record<string, string>>(() => {
  const display = (props.slotDef.display ?? 'inline') as PanelDisplay
  const dw = props.slotDef.drawerSize?.width ?? DEFAULT_W
  const dh = props.slotDef.drawerSize?.height ?? DEFAULT_H
  const style: Record<string, string> = {}
  if (display === 'drawer-left' || display === 'drawer-right') {
    style.width = dw
    style.maxWidth = '100%'
    style.top = '0'
    style.bottom = '0'
    style[display === 'drawer-left' ? 'left' : 'right'] = '0'
  }
  else if (display === 'drawer-bottom') {
    style.height = dh
    style.maxHeight = '100%'
    style.left = '0'
    style.right = '0'
    style.bottom = '0'
  }
  return style
})

const display = computed(() => (props.slotDef.display ?? 'inline') as PanelDisplay)
</script>

<template>
  <div
    ref="anchorEl"
    class="wippy-layout-drawer"
    :class="[
      `wippy-layout-drawer--${display}`,
      drawerOpen && 'wippy-layout-drawer--open',
    ]"
    :style="drawerStyle"
    :aria-hidden="!drawerOpen"
    :data-wippy-panel="slotDef.panel"
    :data-wippy-drawer="display"
    role="dialog"
  >
    <div v-if="!panelDef" class="wippy-layout-drawer__missing">
      Missing panel: "{{ slotDef.panel }}"
    </div>
  </div>
</template>

<style scoped>
.wippy-layout-drawer {
  position: absolute;
  display: flex;
  flex-direction: column;
  overflow: visible;
  color: var(--wippy-layout-drawer-fg, inherit);
  z-index: 900;
  visibility: hidden;
  pointer-events: none;
}
.wippy-layout-drawer--open {
  visibility: visible;
  pointer-events: auto;
}
/*
 * The anchor never moves, so the panel mount over it keeps one rect and a
 * closed drawer stays inside the layout. Only this surface moves. It folds
 * into its edge instead of translating past it, so it stays inside the layout
 * too, and a flat surface looks the same as one that slides.
 */
.wippy-layout-drawer::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--wippy-layout-drawer-bg, var(--wippy-layout-floating-bg, #fff));
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2), 0 2px 6px rgba(0, 0, 0, 0.08);
  visibility: visible;
}
/*
 * Slide animation gated on prefers-reduced-motion. With reduced-motion
 * requested, no `transition` rule applies → transform changes happen
 * instantly (AC §5.7).
 */
@media (prefers-reduced-motion: no-preference) {
  .wippy-layout-drawer::before {
    transition: transform 200ms ease;
  }
}
.wippy-layout-drawer--drawer-left::before { transform: scaleX(0); transform-origin: left; }
.wippy-layout-drawer--drawer-right::before { transform: scaleX(0); transform-origin: right; }
.wippy-layout-drawer--drawer-bottom::before { transform: scaleY(0); transform-origin: bottom; }
.wippy-layout-drawer--open::before { transform: none; }
.wippy-layout-drawer__missing {
  position: relative;
  flex: 1 1 auto;
  display: grid;
  place-items: center;
  color: var(--wippy-layout-error-color, #b00);
  font: 500 0.875rem/1.4 system-ui, sans-serif;
}
</style>
