import type { Ref } from 'vue'
import { watch } from 'vue'

export function useAttentionElement(element: Ref<HTMLElement | null>, publish: () => ((element: HTMLElement | null) => void) | undefined): void {
  watch(element, (value, _previous, cleanup) => {
    const callback = publish()
    callback?.(value)
    cleanup(() => callback?.(null))
  }, { immediate: true, flush: 'post' })
}
