<script setup lang="ts">
/**
 * Position anchor for a panel's rendered content. The actual panel
 * component is rendered ONCE per id at the `LayoutManagerView` level,
 * into an absolutely-positioned mount that overlays this element and is
 * never re-parented. When the breakpoint flips and the layout tree
 * re-renders, this anchor's DOM node is destroyed and a new one created;
 * the mount simply re-targets the new rect, so the panel component
 * instance — and any `<iframe>` inside it — is untouched.
 *
 * This file is intentionally tiny: lay out a flex slot with the
 * correct size / collapsed / fixed styling, and register the slot's
 * DOM element with the anchor registry under its `panel` id.
 *
 * NOTE: this component does NOT provide `LAYOUT_SLOT_KEY`. Panel
 * content is rendered ONCE per id by `LayoutManagerView`'s flat panel
 * zone, which is a sibling of this anchor in the render tree — so
 * anything provided here would never be visible to it.
 * `PanelSlotContext`, which wraps the content in that zone, provides the
 * slot context instead. The template
 * here renders only the "Missing panel" placeholder div, which has no
 * descendants that could call `inject(LAYOUT_SLOT_KEY)`.
 */
import type { LayoutManager } from './layout-manager'
import type { PanelSlot, PanelTree } from './types'
import { computed, inject, onBeforeUnmount, ref, watch } from 'vue'
import { LAYOUT_ANCHOR_REGISTRY_KEY } from './composables'
import { parseSize } from './helpers'
import { panelAnchorName } from './types'

const props = defineProps<{
  slotDef: PanelSlot
  direction: PanelTree['direction']
  manager: LayoutManager
}>()

const panelDef = computed(() => props.manager.getLayout().panels[props.slotDef.panel])

const anchorRegistry = inject(LAYOUT_ANCHOR_REGISTRY_KEY, null)
const anchorEl = ref<HTMLElement | null>(null)

watch(
  () => [anchorEl.value, props.slotDef.panel] as const,
  ([el, panelId], _old, onCleanup) => {
    if (!anchorRegistry || !el)
      return
    anchorRegistry[panelId] = el
    onCleanup(() => {
      // Only clear the registry entry if it still points to OUR
      // element. A breakpoint flip may have already overwritten the
      // entry with a new anchor for the same panelId; in that case
      // the new anchor's mount won.
      if (anchorRegistry[panelId] === el)
        anchorRegistry[panelId] = null
    })
  },
  { immediate: true, flush: 'post' },
)

onBeforeUnmount(() => {
  if (!anchorRegistry)
    return
  const panelId = props.slotDef.panel
  if (anchorRegistry[panelId] === anchorEl.value)
    anchorRegistry[panelId] = null
})

const effectiveSize = computed<string>(() => {
  if (props.slotDef.collapsed)
    return props.slotDef.collapseSize ?? '0px'
  // Type narrowing: `size` is optional on the PanelSlot type to allow
  // drawer-mode slots to omit it. For inline slots (which is everything
  // we'd render here — drawer slots are filtered out by LayoutTree),
  // validateLayout enforces presence at construction time. Treat
  // undefined as the conservative default '1fr' rather than throwing
  // — better degrade gracefully than crash on a malformed runtime mut.
  return props.slotDef.size ?? '1fr'
})

/**
 * Expose this slot as a CSS Anchor Positioning target, so a floating
 * panel can pin itself to the panel it belongs to (`anchor: { panel }`)
 * instead of to the viewport. Costs nothing where the feature is absent —
 * an unknown property is simply dropped.
 */
const anchorNameStyle = computed<Record<string, string>>(() => ({
  anchorName: panelAnchorName(props.slotDef.panel),
}))

const flexStyle = computed<Record<string, string>>(() => {
  const size = effectiveSize.value
  const parsed = parseSize(size)
  const style: Record<string, string> = {}

  // Unit dispatch via parsed result, NOT string-suffix sniffing. parseSize
  // returns null for any value outside the GoldenLayout-style whitelist
  // (auto | Nfr | Npx | N%); validateLayout rejects those at decl-load,
  // but we keep a defensive fallback to `0 0 auto` rather than passing a
  // bad value through to CSS.
  if (!parsed || parsed.unit === 'auto') {
    style.flex = '0 0 auto'
  }
  else if (parsed.unit === 'fr') {
    style.flex = `${parsed.value || 1} 1 0`
  }
  else if (props.slotDef.fixed) {
    // Chrome bands (`fixed: true`) stay at their declared size — no grow,
    // no shrink. Without this, an over-constrained row would compress
    // chrome alongside content panels, which violates §4.1.
    style.flex = `0 0 ${size}`
  }
  else {
    // `0 1 ${size}`: workspace panel — don't grow past declared size, but
    // shrink toward `minSize` when siblings overflow the row. The slot's
    // own `min-width` (set below from `slotDef.minSize`) clamps the floor.
    // Without shrink, three fixed-px workspace panels exceed the viewport
    // and clip off-screen — §5.2 "all panels honor min while keeping
    // total at 100% width".
    style.flex = `0 1 ${size}`
  }

  if (props.slotDef.minSize && !props.slotDef.collapsed) {
    style[props.direction === 'horizontal' ? 'minWidth' : 'minHeight'] = props.slotDef.minSize
  }
  if (props.slotDef.maxSize) {
    style[props.direction === 'horizontal' ? 'maxWidth' : 'maxHeight'] = props.slotDef.maxSize
  }
  return style
})

const title = computed(() => panelDef.value?.title ?? '')
</script>

<template>
  <div
    ref="anchorEl"
    class="wippy-layout-slot"
    :class="[
      slotDef.collapsed && 'wippy-layout-slot--collapsed',
      slotDef.fixed && 'wippy-layout-slot--fixed',
      slotDef.borderBefore && 'wippy-layout-slot--border-before',
      `wippy-layout-slot--${direction}`,
    ]"
    :style="[flexStyle, anchorNameStyle]"
    :aria-label="title || slotDef.panel"
    :data-wippy-panel="slotDef.panel"
  >
    <!--
      Anchor body. Panel content is teleported in by LayoutManagerView's
      flat-render zone — the anchor itself only owns layout / sizing.
      The "Missing panel" placeholder shows when the declared panel id
      has no entry in `panels` at all (consumer typo / removed at runtime).
    -->
    <div v-if="!panelDef" class="wippy-layout-slot__missing">
      Missing panel: "{{ slotDef.panel }}"
    </div>
  </div>
</template>

<style scoped>
.wippy-layout-slot {
  display: flex;
  flex-direction: column;
  overflow: visible;
  position: relative;
  min-width: 0;
  min-height: 0;
}
.wippy-layout-slot--collapsed > * {
  overflow: visible;
}
.wippy-layout-slot__missing {
  flex: 1 1 auto;
  display: grid;
  place-items: center;
  color: var(--wippy-layout-error-color, #b00);
  font: 500 0.875rem/1.4 system-ui, sans-serif;
}
</style>
