import type { ComputedRef, Ref } from 'vue'
import { computed, getCurrentScope, onScopeDispose, ref, watch } from 'vue'

/**
 * Multi-buffered content swapping — the state machine behind "show the
 * next page without flashing the old one away".
 *
 * A *buffer* (or slot) holds one piece of content and stays mounted
 * while a sibling buffer loads the next one. When the incoming buffer
 * signals it has painted, it becomes active and the outgoing one
 * retires. Because retired buffers stay mounted, navigating back to
 * content that is still buffered reuses the live DOM — which for an
 * `<iframe>` means no reload and no lost state.
 *
 * This module owns *only* the bookkeeping: which buffer holds what, which
 * is active, which has painted, which failed. It renders nothing and
 * imposes no styling: the caller renders one element per buffer and binds
 * its own classes off `slots` / `topIndex` / `showLoader`. `w-page.vue` in
 * the Web Host is the reference consumer.
 *
 * ## Why buffer identity is an index, not a key
 *
 * `slots` is a fixed-length array and a slot's `index` never changes.
 * Callers **must** key their render loop on `slot.index`, never on
 * `slot.key`. Keying on content makes Vue reorder DOM nodes on every
 * swap, and a reordered `<iframe>` is detached and reinserted — which
 * browsers treat as a fresh navigation, reloading the document and
 * destroying exactly the state this module exists to preserve. The same
 * constraint governs the panel mount zone in `LayoutManagerView`.
 */

/**
 * Which buffer to overwrite when new content arrives and no buffer
 * already holds it.
 *
 * - `round-robin` — advance to the next index, wrapping. For two
 *   buffers this alternates, which is the historical Web Host
 *   behaviour. For three or more it can evict the *more* recently used
 *   of the candidates, so it is not a good default beyond two.
 * - `lru` — overwrite whichever inactive buffer was active longest ago.
 */
export type SwapEvictPolicy = 'round-robin' | 'lru'

/**
 * What `push` hands back: which buffer took the content, and under what
 * key. Everything mutable is deliberately absent — read it live from
 * `slots.value[index]`.
 */
export interface SwapSlotHandle {
  readonly index: number
  readonly key: string
}

export interface SwapSlot<E> {
  /** Fixed buffer position. Stable for the lifetime of the buffer — use as the render key. */
  readonly index: number
  /** Identity of the content, from `keyOf`. Equal keys reuse this buffer instead of allocating. */
  readonly key: string
  /** Caller-defined payload describing what to render. */
  readonly entry: E
  /** The content has signalled that it has painted. */
  readonly ready: boolean
  /**
   * Loading/render failure for **this buffer specifically**. Scoped per
   * buffer on purpose: one buffer failing must not tear down a sibling
   * that is holding perfectly good content, or navigating away from a
   * broken page and back destroys the page you came from too.
   */
  readonly error: unknown | null
  /**
   * Monotonic stamp of the last time this buffer became active. `lru`
   * eviction picks the smallest. Never reset, so it also serves as a
   * "has been used" marker.
   */
  readonly lastActiveAt: number
}

export interface SwapBufferOptions<E> {
  /**
   * Derive a stable identity for a piece of content. Two entries with
   * the same key are the same content, and pushing one when the other
   * is already buffered reuses that buffer rather than remounting.
   *
   * Must not read a clock or any other value that changes between calls
   * for identical content — an unstable key defeats reuse entirely and
   * forces a remount on every push.
   */
  keyOf: (entry: E) => string
  /** Number of buffers. `1` disables reuse; `2` is the classic double buffer. Default `2`. */
  buffers?: number
  /** Eviction policy when every buffer is occupied. Default `round-robin`. */
  evict?: SwapEvictPolicy
  /**
   * Ceiling on how long a buffer may stay un-revealed waiting to paint.
   *
   * Readiness is reported by the content, and content can fail to report:
   * a bundle that throws before its ready hook, a module that never
   * evaluates, a component that simply doesn't emit. Without a ceiling the
   * buffer waits forever and the user stares at a loader over stale
   * content with no error — the worst possible outcome, because nothing
   * anywhere says anything is wrong.
   *
   * `0` or `Infinity` disables the ceiling. Default `8000`.
   */
  readyTimeoutMs?: number
  /**
   * What the ceiling does when it fires.
   *
   * `reveal` (default) shows the content anyway — it is usually painted
   * and merely silent, so revealing beats hiding it forever. `fail` marks
   * the buffer errored instead, for callers that would rather surface a
   * problem than show something possibly blank.
   */
  onReadyTimeout?: 'reveal' | 'fail'
  /**
   * Called when the ceiling fires, before the reveal/fail is applied.
   * A timeout is a real defect in the content, not a cosmetic event —
   * hosts should log it rather than let it pass silently.
   */
  onReadyTimeoutFired?: (slot: SwapSlot<E>) => void
  /**
   * Hold the loading indicator back this long. Content that resolves from
   * cache in 30ms should not produce a 30ms strobe of spinner — that
   * flash is itself the ugly transition people notice. Default `250`.
   */
  loaderDelayMs?: number
  /**
   * Once shown, keep the indicator up at least this long. Without a floor,
   * content that resolves just after `loaderDelayMs` makes the spinner
   * appear and vanish in the same breath, which reads as a glitch rather
   * than as loading. Default `400`.
   */
  loaderMinMs?: number
  /**
   * Called with the slot that is about to be overwritten, before the
   * overwrite. Use it to release resources keyed to the outgoing
   * content. Not called when a buffer is reused (same key) or when an
   * empty buffer is filled.
   */
  onEvict?: (slot: SwapSlot<E>) => void
}

export interface SwapBuffer<E> {
  /** All buffers, in index order. `null` means "never filled". */
  readonly slots: Ref<(SwapSlot<E> | null)[]>
  /** Index of the buffer that currently owns the content. */
  readonly topIndex: Ref<number>
  /** The active buffer, or `null` before the first push. */
  readonly active: ComputedRef<SwapSlot<E> | null>
  /**
   * Whether a loading indicator should be on screen — already debounced
   * by `loaderDelayMs` and floored by `loaderMinMs`. Bind visibility to
   * this rather than to "is the active buffer un-ready", or fast content
   * produces a flash.
   */
  readonly showLoader: Ref<boolean>
  /**
   * Route `entry` to a buffer. Reuses the buffer already holding this
   * key (preserving its `ready` state and any prior error), otherwise
   * evicts one per policy. Either way the target becomes active
   * immediately — activation is not deferred until the content paints,
   * because the caller needs to start routing input to it right away.
   *
   * Returns a HANDLE, not the slot: every mutation replaces the slot
   * object, so a returned `SwapSlot` would silently freeze at allocation.
   * Read live state via `slots.value[handle.index]`.
   */
  push: (entry: E) => SwapSlotHandle
  /**
   * Mark a buffer as painted. No-op for an empty buffer.
   *
   * Pass `key` whenever the signal is asynchronous. Buffers are recycled,
   * so a late callback from content that has since been evicted would
   * otherwise mark whatever now occupies that index — revealing unpainted
   * content and cancelling its reveal ceiling. With `key` the call is
   * ignored unless the buffer still holds the content that sent it.
   */
  markReady: (index: number, key?: string) => void
  /** Record a failure against a buffer. Same `key` guard as `markReady`. */
  markFailed: (index: number, error: unknown, key?: string) => void
  /** Clear a buffer's error without touching its `ready` state. */
  clearError: (index: number) => void
  /**
   * Cancel every pending timer. Called automatically on scope teardown
   * when constructed inside a component or `effectScope`; call it
   * yourself when constructing outside one.
   */
  dispose: () => void
}

/**
 * Create a swap buffer.
 *
 * The returned refs are reactive; mutate only through the methods.
 *
 * ```ts
 * const swap = useSwapBuffer<PageEntry>({ keyOf: e => e.queryKey.join(',') })
 * watch(source, entry => swap.push(entry), { immediate: true })
 * // template: v-for="slot in swap.slots" :key="slot.index"
 * ```
 */
export function useSwapBuffer<E>(options: SwapBufferOptions<E>): SwapBuffer<E> {
  const bufferCount = Math.max(1, Math.floor(options.buffers ?? 2))
  const policy: SwapEvictPolicy = options.evict ?? 'round-robin'

  const slots = ref<(SwapSlot<E> | null)[]>(
    Array.from<SwapSlot<E> | null>({ length: bufferCount }).fill(null),
  ) as Ref<(SwapSlot<E> | null)[]>

  // Starts at 0 so the first `push` under `round-robin` lands in buffer
  // 1, leaving buffer 0 free. Historical behaviour; harmless, and
  // preserved so an extraction of an existing double buffer is
  // observably identical.
  const topIndex = ref(0)

  // Activation counter for `lru`. Monotonic, starts at 1 so that 0 can
  // mean "never active".
  let activationClock = 0

  const active = computed(() => slots.value[topIndex.value] ?? null)

  /**
   * The buffer ON SCREEN — not `topIndex`, which `push` promotes before
   * the content paints. That is the newest buffer to report ready; `-1`
   * before anything has.
   */
  function visibleIndex(): number {
    let found = -1
    let newest = 0
    for (let i = 0; i < slots.value.length; i++) {
      const slot = slots.value[i]
      if (!slot?.ready)
        continue
      if (slot.lastActiveAt >= newest) {
        newest = slot.lastActiveAt
        found = i
      }
    }
    return found
  }

  // ── Reveal ceiling ──────────────────────────────────────────────────
  // One timer per occupied buffer, keyed by buffer index. Armed when a
  // buffer takes new content, cleared the moment it reports ready or
  // failed, and re-armed on reuse only if the buffer is not already
  // painted (reused content has nothing left to wait for).
  const readyTimeoutMs = options.readyTimeoutMs ?? 8000
  const timeoutMode = options.onReadyTimeout ?? 'reveal'
  const ceilingEnabled = Number.isFinite(readyTimeoutMs) && readyTimeoutMs > 0
  const timers = new Map<number, ReturnType<typeof setTimeout>>()

  function clearTimer(index: number) {
    const t = timers.get(index)
    if (t !== undefined) {
      clearTimeout(t)
      timers.delete(index)
    }
  }

  function armTimer(index: number) {
    if (!ceilingEnabled)
      return
    clearTimer(index)
    timers.set(index, setTimeout(() => {
      timers.delete(index)
      const slot = slots.value[index]
      // Raced with a real ready/fail, or the buffer was evicted out from
      // under the timer — either way there is nothing left to rescue.
      if (!slot || slot.ready || slot.error)
        return
      // A throwing diagnostic must not prevent the reveal — that would
      // turn the hook meant to surface a stall into the cause of one.
      try {
        options.onReadyTimeoutFired?.(slot)
      }
      catch {}
      if (timeoutMode === 'fail') {
        patch(index, { error: new Error(`[swap-buffer] content "${slot.key}" did not report ready within ${readyTimeoutMs}ms`) })
      }
      else {
        patch(index, { ready: true })
      }
    }, readyTimeoutMs))
  }

  // ── Loader debounce ─────────────────────────────────────────────────
  // Two guards, doing opposite jobs: `delay` suppresses the indicator for
  // content that resolves quickly, `min` keeps it up long enough to read
  // once it has appeared. Together they turn "spinner flashes on every
  // navigation" into "spinner appears only when there is a real wait".
  const loaderDelayMs = options.loaderDelayMs ?? 250
  const loaderMinMs = options.loaderMinMs ?? 400
  const showLoader = ref(false)
  let loaderDelayTimer: ReturnType<typeof setTimeout> | undefined
  let loaderHideTimer: ReturnType<typeof setTimeout> | undefined
  let loaderShownAt = 0

  function clearLoaderTimers() {
    if (loaderDelayTimer !== undefined) {
      clearTimeout(loaderDelayTimer)
      loaderDelayTimer = undefined
    }
    if (loaderHideTimer !== undefined) {
      clearTimeout(loaderHideTimer)
      loaderHideTimer = undefined
    }
  }

  /** True while the active buffer is waiting to paint and has not failed. */
  const isPending = computed(() => {
    const slot = active.value
    return slot !== null && !slot.ready && !slot.error
  })

  const stopPendingWatch = watch(isPending, (pending) => {
    if (pending) {
      // Cancel any hide still owed to the PREVIOUS load before deciding
      // what to do. Without this, a hide armed by the last resolve keeps
      // running against the new content and turns the indicator off
      // mid-load — and since `isPending` is already true, nothing ever
      // turns it back on.
      if (loaderHideTimer !== undefined) {
        clearTimeout(loaderHideTimer)
        loaderHideTimer = undefined
      }
      if (showLoader.value || loaderDelayTimer !== undefined)
        return
      loaderDelayTimer = setTimeout(() => {
        loaderDelayTimer = undefined
        showLoader.value = true
        loaderShownAt = Date.now()
      }, loaderDelayMs)
      return
    }

    // Resolved. Either it never got shown (cancel the pending reveal) or
    // it is on screen and owes the viewer its minimum legible time.
    if (loaderDelayTimer !== undefined) {
      clearTimeout(loaderDelayTimer)
      loaderDelayTimer = undefined
    }
    if (!showLoader.value)
      return
    const remaining = Math.max(0, loaderMinMs - (Date.now() - loaderShownAt))
    if (remaining === 0) {
      showLoader.value = false
      return
    }
    if (loaderHideTimer !== undefined)
      clearTimeout(loaderHideTimer)
    loaderHideTimer = setTimeout(() => {
      loaderHideTimer = undefined
      showLoader.value = false
    }, remaining)
  }, { immediate: true })

  function dispose() {
    for (const t of timers.values())
      clearTimeout(t)
    timers.clear()
    clearLoaderTimers()
    // The loader watcher arms `loaderDelayTimer`, so leaving it running
    // would let the next `push` re-create a timer this call just cleared.
    // It has no owning scope in the one situation `dispose` exists for —
    // construction outside a component — so it must be stopped by hand.
    stopPendingWatch()
  }

  // Auto-cleanup when constructed inside a component / effect scope, which
  // is the normal case. Callers outside a scope get `dispose()` to call.
  if (getCurrentScope())
    onScopeDispose(dispose)

  function pickVictim(): number {
    // Neither branch special-cases empty buffers, and neither needs to:
    // `round-robin` sweeps every index in turn, and an unfilled buffer
    // reads as `lastActiveAt: 0` — already the `lru` minimum. Adding an
    // empty-first preference would only change *which* index new content
    // lands in, which mirrors the slot assignment of an existing double
    // buffer for no behavioural gain.
    if (policy === 'lru') {
      // `topIndex` is the INCOMING buffer, not the visible one: `push`
      // makes a slot top immediately and its content may not have painted
      // yet. What the user is actually looking at is the newest buffer
      // that has reported ready — so protecting `topIndex` alone would
      // leave the one thing on screen evictable. At `buffers: 2` the two
      // coincide often enough to hide this; at 3+ it is reachable in four
      // pushes.
      const onScreen = visibleIndex()
      let victim = -1
      let oldest = Number.POSITIVE_INFINITY
      for (let i = 0; i < slots.value.length; i++) {
        if (i === topIndex.value || i === onScreen)
          continue
        const stamp = slots.value[i]?.lastActiveAt ?? 0
        if (stamp < oldest) {
          oldest = stamp
          victim = i
        }
      }
      // Every buffer is spoken for — the incoming one is the only thing
      // left to recycle, as in a single-buffer configuration.
      return victim === -1 ? topIndex.value : victim
    }

    return (topIndex.value + 1) % slots.value.length
  }

  function push(entry: E): SwapSlotHandle {
    const key = options.keyOf(entry)
    const existing = slots.value.findIndex(s => s !== null && s.key === key)

    if (existing !== -1) {
      const prev = slots.value[existing] as SwapSlot<E>
      // Reuse: the content is already mounted. Refresh the payload (the
      // route may have moved within the same page) but keep `ready` —
      // re-arming it would hide a live, painted buffer behind a loader
      // that nothing will ever clear, since already-loaded content does
      // not emit a second load.
      const next: SwapSlot<E> = {
        ...prev,
        entry,
        // `error` is deliberately carried over. Reuse fires on any
        // re-push of the same key — including a sub-route change within
        // the same page — and clearing here would remount the failed
        // content and refetch a known-bad endpoint on every one of them.
        // Recovering from a failure is an explicit act: call `clearError`.
        lastActiveAt: ++activationClock,
      }
      slots.value[existing] = next
      topIndex.value = existing
      // Painted or failed content has nothing left to report. A buffer
      // still waiting keeps the ceiling it already has — re-arming would
      // let a page that has been silently stalling for 7.9s win a fresh
      // 8s on every revisit, so a user bouncing between two pages could
      // never trip it.
      if (!next.ready && !next.error && !timers.has(existing))
        armTimer(existing)
      return { index: existing, key }
    }

    const target = pickVictim()
    const evicted = slots.value[target]
    if (evicted && options.onEvict)
      options.onEvict(evicted)
    clearTimer(target)

    const next: SwapSlot<E> = {
      index: target,
      key,
      entry,
      ready: false,
      error: null,
      lastActiveAt: ++activationClock,
    }
    slots.value[target] = next
    topIndex.value = target
    armTimer(target)
    return { index: target, key }
  }

  /**
   * Does buffer `index` still hold the content `key` came from? An
   * omitted key means the caller is synchronous and cannot be stale.
   */
  function ownsKey(index: number, key: string | undefined) {
    return key === undefined || slots.value[index]?.key === key
  }

  function patch(index: number, changes: Partial<SwapSlot<E>>) {
    const cur = slots.value[index]
    if (!cur)
      return
    slots.value[index] = { ...cur, ...changes }
  }

  return {
    slots,
    topIndex,
    active,
    showLoader,
    push,
    markReady: (index, key) => {
      if (!ownsKey(index, key))
        return
      clearTimer(index)
      patch(index, { ready: true })
    },
    markFailed: (index, error, key) => {
      if (!ownsKey(index, key))
        return
      clearTimer(index)
      patch(index, { error })
    },
    clearError: (index) => {
      patch(index, { error: null })
      // Re-arm the ceiling. `markFailed` cleared it, so a buffer that is
      // cleared but not ready would otherwise sit pending with no timer
      // and nothing able to mark it — the loader stays up forever. That
      // is the documented recovery path, so it has to terminate.
      const slot = slots.value[index]
      if (slot && !slot.ready)
        armTimer(index)
    },
    dispose,
  }
}
