import type {
  LayoutDeclaration,
  ModalDef,
  ModalSize,
  PanelSlot,
  PanelTarget,
  PanelTree,
  ValidationIssue,
} from './types'
import { DEFAULT_BREAKPOINTS, LayoutValidationError } from './types'

// ────────────────────────────────────────────────────────────────
// Type guards
// ────────────────────────────────────────────────────────────────

export function isPanelSlot(node: PanelSlot | PanelTree): node is PanelSlot {
  return typeof (node as PanelSlot).panel === 'string'
}

export function isPanelTree(node: PanelSlot | PanelTree): node is PanelTree {
  return Array.isArray((node as PanelTree).children)
}

const VALID_DISPLAY_VALUES: ReadonlySet<string> = new Set([
  'inline',
  'drawer-left',
  'drawer-right',
  'drawer-bottom',
])
const VALID_PANEL_DIVIDERS: ReadonlySet<string> = new Set(['default', 'none', 'line'])

/**
 * True when the slot renders into the in-tree grid (the default case).
 * Drawer-mode slots return false — they do NOT participate in flex sizing.
 */
export function isInlineSlot(slot: PanelSlot): boolean {
  return slot.display === undefined || slot.display === 'inline'
}

/**
 * True when a splitter between two siblings would have at least one
 * resizable side. A side is "resizable" if it's a non-fixed,
 * non-collapsed slot. Trees are not directly resizable today (would
 * require a tree-id mechanism — see Phase 6 / paired-resize).
 *
 * Used by LayoutTree to gate splitter rendering: between two fixed
 * chrome bands (or between a fixed chrome and a non-resizable
 * neighbor), no splitter is rendered. AC §4.1: chrome panels are
 * never resizable.
 */
export function hasResizableSide(
  before: PanelSlot | PanelTree | null,
  after: PanelSlot | PanelTree | null,
): boolean {
  const beforeResizable = !!before && isPanelSlot(before) && !before.fixed && !before.collapsed
  const afterResizable = !!after && isPanelSlot(after) && !after.fixed && !after.collapsed
  return beforeResizable || afterResizable
}

/**
 * True when the slot is rendered as a drawer overlay rather than in-grid.
 */
export function isDrawerSlot(slot: PanelSlot): boolean {
  return !isInlineSlot(slot)
}

// ────────────────────────────────────────────────────────────────
// Size grammar — GoldenLayout v2 alignment
// ────────────────────────────────────────────────────────────────
//
// Mature JS panel managers (VS Code, dockview, rc-dock, react-mosaic,
// react-resizable-panels, GoldenLayout v2) all converge on a tight
// scalar grammar — none accept `clamp()`, `minmax()`, `min-content`,
// `calc()`, or arbitrary CSS expressions. The reason is structural:
// once the size value is a CSS expression you've delegated layout to
// the browser's grid engine, which gives no hooks for paired-clamp
// splitter math, persistence, snap, programmatic setSize, or animated
// reflow. We follow the same pattern.
//
// Accepted formats (size, drawerSize.width/height):
//   • `auto`       — content-driven intrinsic size
//   • `Nfr`        — flex weight (1fr = "fill remaining space")
//   • `Npx`        — fixed pixels
//   • `N%`         — percent of parent's main axis
//
// Min/max sizes accept ONLY `Npx`. Embedding min/max in the size value
// (`minmax(...)`, `clamp(...)`) would require re-implementing the CSS
// grid track-sizing algorithm in JS — separate scalar fields are the
// industry pattern (see GoldenLayout v2 `minSize: '200px'`, dockview
// `minimumWidth: 200`, VS Code splitview `minimumSize: 200`).

const SIZE_PATTERN = /^(?:auto|\d+(?:\.\d+)?(?:fr|px|%))$/
const PIXEL_PATTERN = /^\d+(?:\.\d+)?px$/

/**
 * Parsed slot-size value. Returned by `parseSize` for unambiguous unit
 * dispatch in flex-style derivation and the splitter's fr-absorber check.
 */
export type ParsedSize
  = | { unit: 'auto' }
    | { unit: 'fr', value: number }
    | { unit: 'px', value: number }
    | { unit: '%', value: number }

/**
 * Parse a size string per the grammar above. Returns null for any value
 * outside the whitelist (em/rem/vh/vw/clamp()/minmax()/etc.) — callers
 * should treat null as "invalid; fall back to default flex" rather than
 * passing the raw string through to CSS.
 *
 * Edge cases:
 *   - Case-sensitive (`'1FR'` rejected). CSS is case-insensitive but the
 *     panel-manager grammar is tighter — keeps source matching trivial.
 *   - Leading-digit required (`'.5fr'` rejected even though CSS accepts).
 *   - Negative values rejected (regex `^\d+`). Negative px is meaningless;
 *     negative fr would invert flex distribution in confusing ways.
 *   - Zero values accepted: `'0px'` (legitimate — see `host-coordinator-
 *     mount.vue` for a zero-size synthetic slot) and `'0fr'` (degenerate
 *     but harmless — `LayoutPanelSlot.flexStyle` falls back to grow=1
 *     via `value || 1`, so `0fr` renders identically to `1fr`).
 */
export function parseSize(s: string | undefined): ParsedSize | null {
  if (!s)
    return null
  if (s === 'auto')
    return { unit: 'auto' }
  const m = /^(\d+(?:\.\d+)?)(fr|px|%)$/.exec(s)
  if (!m)
    return null
  return { unit: m[2] as 'fr' | 'px' | '%', value: Number.parseFloat(m[1]) }
}

/**
 * Parse a `Npx` string, returning the numeric pixel value or null. Used
 * for `minSize` / `maxSize` / `drawerSize` where the grammar is
 * pixel-only (mirrors GoldenLayout v2 / dockview / VS Code conventions).
 */
export function parsePixelSize(s: string | undefined): number | null {
  if (!s)
    return null
  const m = /^(\d+(?:\.\d+)?)px$/.exec(s)
  return m ? Number.parseFloat(m[1]) : null
}

function validateSize(size: string): boolean {
  return SIZE_PATTERN.test(size)
}

function validatePixelSize(size: string): boolean {
  return PIXEL_PATTERN.test(size)
}

/**
 * Recursively walk a PanelTree, calling visitor for each slot.
 * Callers pass back true/false if they want to stop early.
 */
export function walkTree(
  tree: PanelTree,
  visitSlot: (slot: PanelSlot, path: number[]) => void,
  visitTree?: (subtree: PanelTree, path: number[]) => void,
  path: number[] = [],
): void {
  visitTree?.(tree, path)
  tree.children.forEach((child, i) => {
    const childPath = [...path, i]
    if (isPanelSlot(child)) {
      visitSlot(child, childPath)
    }
    else {
      walkTree(child, visitSlot, visitTree, childPath)
    }
  })
}

/**
 * Validate a layout declaration. Returns an array of issues (empty if valid).
 * Does NOT throw — callers choose how to handle issues.
 */
export function validateLayout(decl: LayoutDeclaration): ValidationIssue[] {
  const issues: ValidationIssue[] = []

  // layouts.default is required (enforced by the type, but double-check at runtime)
  if (!decl.layouts?.default) {
    issues.push({
      kind: 'empty-tree',
      message: 'layouts.default is required',
    })
    return issues
  }

  // Collect all panel IDs referenced by every breakpoint layout
  const referencedIds = new Set<string>()
  const duplicatesPerBreakpoint = new Map<string, string[]>()

  for (const [breakpointName, tree] of Object.entries(decl.layouts)) {
    if (!tree)
      continue
    if (tree.children.length === 0) {
      issues.push({
        kind: 'empty-tree',
        message: `layouts.${breakpointName} has no children`,
      })
      continue
    }

    const seenInBreakpoint = new Set<string>()
    const dupes: string[] = []

    // Nested trees may carry their own `size` (same grammar as slots).
    // The root has no parent track, so its `size` is ignored and not checked.
    walkTree(tree, () => {}, (subtree, path) => {
      if (path.length > 0 && subtree.size !== undefined && !validateSize(subtree.size)) {
        issues.push({
          kind: 'bad-size',
          message: `nested tree at layouts.${breakpointName}[${path.join('][')}] has invalid size "${subtree.size}" (must be auto, Nfr, Npx, or N% — e.g. "1fr", "320px", "50%", "auto")`,
        })
      }
    })

    walkTree(tree, (slot) => {
      referencedIds.add(slot.panel)

      if (seenInBreakpoint.has(slot.panel)) {
        dupes.push(slot.panel)
      }
      else {
        seenInBreakpoint.add(slot.panel)
      }

      // Validate display field if present
      const display = slot.display
      if (display !== undefined && !VALID_DISPLAY_VALUES.has(display)) {
        issues.push({
          kind: 'bad-display',
          message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid display "${display}" (expected one of: inline, drawer-left, drawer-right, drawer-bottom)`,
          panelId: slot.panel,
        })
      }

      const dividerBefore = slot.dividerBefore
      if (dividerBefore !== undefined && !VALID_PANEL_DIVIDERS.has(dividerBefore)) {
        issues.push({
          kind: 'bad-divider',
          message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid dividerBefore "${dividerBefore}" (expected one of: default, none, line)`,
          panelId: slot.panel,
        })
      }

      if (slot.borderBefore !== undefined && typeof slot.borderBefore !== 'boolean') {
        issues.push({
          kind: 'bad-border-before',
          message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid borderBefore "${slot.borderBefore}" (expected boolean)`,
          panelId: slot.panel,
        })
      }

      // Inline slots require a `size` and respect min/max. Drawer slots
      // ignore grid sizing entirely (they render as overlays); skip
      // size validation for them.
      if (isInlineSlot(slot)) {
        if (slot.size === undefined) {
          issues.push({
            kind: 'missing-size',
            message: `panel "${slot.panel}" in layouts.${breakpointName} is missing required size (inline slots must declare size)`,
            panelId: slot.panel,
          })
        }
        else if (!validateSize(slot.size)) {
          issues.push({
            kind: 'bad-size',
            message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid size "${slot.size}" (must be auto, Nfr, Npx, or N% — e.g. "1fr", "200px", "50%", "auto")`,
            panelId: slot.panel,
          })
        }
        if (slot.minSize && !validatePixelSize(slot.minSize)) {
          issues.push({
            kind: 'bad-size',
            message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid minSize "${slot.minSize}" (must be Npx, e.g. "200px")`,
            panelId: slot.panel,
          })
        }
        if (slot.maxSize && !validatePixelSize(slot.maxSize)) {
          issues.push({
            kind: 'bad-size',
            message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid maxSize "${slot.maxSize}" (must be Npx, e.g. "800px")`,
            panelId: slot.panel,
          })
        }
      }
      else {
        // Drawer-mode slots: drawerSize is a fixed dimension when the
        // drawer is open. Pixel-only — fr/% don't make sense for a
        // free-floating overlay's intrinsic dimension.
        if (slot.drawerSize?.width && !validatePixelSize(slot.drawerSize.width)) {
          issues.push({
            kind: 'bad-size',
            message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid drawerSize.width "${slot.drawerSize.width}" (must be Npx)`,
            panelId: slot.panel,
          })
        }
        if (slot.drawerSize?.height && !validatePixelSize(slot.drawerSize.height)) {
          issues.push({
            kind: 'bad-size',
            message: `panel "${slot.panel}" in layouts.${breakpointName} has invalid drawerSize.height "${slot.drawerSize.height}" (must be Npx)`,
            panelId: slot.panel,
          })
        }
      }
    })

    if (dupes.length > 0) {
      duplicatesPerBreakpoint.set(breakpointName, dupes)
    }
  }

  for (const [breakpointName, dupes] of duplicatesPerBreakpoint) {
    issues.push({
      kind: 'duplicate-id',
      message: `layouts.${breakpointName} references panels ${dupes.map(d => `"${d}"`).join(', ')} more than once — each panel can only appear once per breakpoint layout`,
      panelIds: dupes,
    })
  }

  // Every referenced id must exist in panels map
  for (const id of referencedIds) {
    if (!decl.panels[id]) {
      issues.push({
        kind: 'orphan-ref',
        message: `panel id "${id}" is referenced in a layout but not declared in panels map`,
        panelId: id,
      })
    }
  }

  // Validate breakpoint overrides make sense
  if (decl.breakpoints) {
    for (const [name, threshold] of Object.entries(decl.breakpoints)) {
      if (typeof threshold !== 'number' || threshold <= 0) {
        issues.push({
          kind: 'unknown-breakpoint',
          message: `breakpoint "${name}" has invalid threshold "${String(threshold)}" — must be a positive number`,
        })
      }
    }
  }

  return issues
}

/**
 * Throw on any validation issue. Convenience wrapper around `validateLayout`.
 */
export function assertValidLayout(decl: LayoutDeclaration): void {
  const issues = validateLayout(decl)
  if (issues.length > 0) {
    throw new LayoutValidationError(issues)
  }
}

/**
 * Validate a `ModalDef` shape. Catches obviously-wrong inputs before they
 * reach the renderer (where the failure mode is a blank modal with no
 * stack trace pointing back at the caller). Symmetric to `assertValidLayout`
 * — used by `openModal(id, def)` and `registerModal(id, def)` so a bad
 * def fails fast at the mutation site.
 */
export function assertValidModalDef(id: string, def: ModalDef): void {
  const issues: ValidationIssue[] = []
  // `typeof null === 'object'` and `typeof [] === 'object'` — both are
  // wrong for a ModalDef. Reject them with a precise error so a
  // common mistake (`registerModal('x', [])`) doesn't fall through to
  // the missing-component branch with a misleading message.
  if (def === null || typeof def !== 'object' || Array.isArray(def)) {
    issues.push({
      kind: 'bad-modal-def',
      message: `[@wippy-fe/layout] modal "${id}": def must be a plain object`,
    })
  }
  else if (!def.component) {
    issues.push({
      kind: 'bad-modal-def',
      message: `[@wippy-fe/layout] modal "${id}": def.component is required`,
    })
  }
  if (issues.length > 0)
    throw new LayoutValidationError(issues)
}

// ────────────────────────────────────────────────────────────────
// Modal size resolution (shared by LayoutModal + LayoutModalNative)
// ────────────────────────────────────────────────────────────────

/**
 * Default modal sizing applied when a `ModalSize` field is omitted.
 * Single source of truth — both `LayoutModal` and `LayoutModalNative`
 * pull from here so the visual contract stays in lock-step across the
 * legacy div-overlay and native `<dialog>` paths.
 */
export const MODAL_SIZE_DEFAULTS = {
  width: '500px',
  height: 'auto',
  maxWidth: '90vw',
  maxHeight: '90vh',
} as const

/**
 * Resolve the active `ModalSize` for the current breakpoint. Supports
 * both `ModalDef['size']` shapes:
 *   1. a single `ModalSize` — applied at every breakpoint
 *   2. a `Record<breakpointName, ModalSize>` — picks the breakpoint
 *      entry, falling back to `default`
 */
export function resolveModalSize(
  size: ModalDef['size'],
  bp: string,
): ModalSize | undefined {
  if (!size)
    return undefined
  if (typeof (size as ModalSize).width === 'string')
    return size as ModalSize
  const map = size as Record<string, ModalSize>
  return map[bp] ?? map.default
}

/**
 * Resolve the final inline-style object for the modal dialog element.
 * Combines `resolveModalSize` with `MODAL_SIZE_DEFAULTS`.
 */
export function resolveModalDialogStyle(
  size: ModalDef['size'],
  bp: string,
): Record<string, string> {
  const s = resolveModalSize(size, bp)
  return {
    width: s?.width ?? MODAL_SIZE_DEFAULTS.width,
    height: s?.height ?? MODAL_SIZE_DEFAULTS.height,
    maxWidth: s?.maxWidth ?? MODAL_SIZE_DEFAULTS.maxWidth,
    maxHeight: MODAL_SIZE_DEFAULTS.maxHeight,
  }
}

// ────────────────────────────────────────────────────────────────
// Breakpoint picker
// ────────────────────────────────────────────────────────────────

/**
 * Given a container width + a declaration, pick the active breakpoint name.
 * Width-descending match: returns the largest declared breakpoint whose
 * threshold is <= width, or 'default' if none match.
 */
export function pickBreakpoint(
  containerWidth: number,
  decl: LayoutDeclaration,
): string {
  const thresholds = { ...DEFAULT_BREAKPOINTS, ...(decl.breakpoints ?? {}) }
  // Only consider breakpoints that have a corresponding layout declared
  const candidates = Object.entries(thresholds)
    .filter(([name]) => decl.layouts[name])
    .sort((a, b) => b[1] - a[1]) // desc by threshold

  for (const [name, threshold] of candidates) {
    if (containerWidth >= threshold) {
      return name
    }
  }
  return 'default'
}

// ────────────────────────────────────────────────────────────────
// Derive mobile (fallback when no narrow breakpoint declared)
// ────────────────────────────────────────────────────────────────

/**
 * Derive a single-panel fallback layout. Given a declaration, returns a
 * PanelTree with only the first slot of the default layout. Useful when
 * no `sm` (or similar narrow) breakpoint is declared but the container
 * has shrunk below the smallest declared breakpoint.
 */
export function deriveMobileLayout(decl: LayoutDeclaration): PanelTree {
  // Find first slot in default layout
  let firstSlot: PanelSlot | null = null
  walkTree(decl.layouts.default, (slot) => {
    if (!firstSlot)
      firstSlot = slot
  })

  if (!firstSlot) {
    return { direction: 'vertical', children: [] }
  }

  return {
    direction: 'vertical',
    children: [
      { panel: (firstSlot as PanelSlot).panel, size: '1fr', fixed: true },
    ],
  }
}

// ────────────────────────────────────────────────────────────────
// Tree mutation helpers (used by addPanel / removePanel / movePanel)
// ────────────────────────────────────────────────────────────────

/**
 * Find the parent tree + index of a slot by panel id. Mutates nothing.
 * Returns null if not found.
 */
export function findSlotParent(
  tree: PanelTree,
  panelId: string,
): { parent: PanelTree, index: number } | null {
  for (let i = 0; i < tree.children.length; i++) {
    const child = tree.children[i]
    if (isPanelSlot(child) && child.panel === panelId) {
      return { parent: tree, index: i }
    }
    if (isPanelTree(child)) {
      const found = findSlotParent(child, panelId)
      if (found)
        return found
    }
  }
  return null
}

/**
 * Remove a slot from its parent by panel id. Returns the removed slot
 * or null if not found. Mutates the tree in place.
 * Collapses empty parent trees (but not the root).
 */
export function removeNode(tree: PanelTree, panelId: string): PanelSlot | null {
  const found = findSlotParent(tree, panelId)
  if (!found)
    return null
  const [removed] = found.parent.children.splice(found.index, 1) as PanelSlot[]

  // Recursively collapse empty parent trees, but never the outer root
  collapseEmptyChildren(tree)

  return removed
}

/**
 * Recursively collapse empty nested trees (but preserve the root, even if empty).
 * Called internally by removeNode.
 */
function collapseEmptyChildren(tree: PanelTree): void {
  tree.children = tree.children.filter((child) => {
    if (isPanelTree(child)) {
      collapseEmptyChildren(child)
      return child.children.length > 0
    }
    return true
  })
}

/**
 * Insert a slot at a target position. Mutates the tree in place.
 *
 * - `target.relativeTo` names an existing panel; the new slot is placed on
 *   the given side of that panel's parent (creating a nested tree if the
 *   direction differs from the drop side).
 * - Omit `target.relativeTo` to append at the root in its natural direction.
 */
export function insertAtPosition(
  tree: PanelTree,
  slot: PanelSlot,
  target: PanelTarget,
): void {
  if (!target.relativeTo) {
    // Append to root
    tree.children.push(slot)
    return
  }

  const found = findSlotParent(tree, target.relativeTo)
  if (!found) {
    // relativeTo not found — append to root as fallback
    tree.children.push(slot)
    return
  }

  const { parent, index } = found
  const dropPosition = target.position

  if (dropPosition === 'center') {
    // Replace the existing slot (consumer intended swap; remove old first)
    parent.children.splice(index, 1, slot)
    return
  }

  const dropIsHorizontal = dropPosition === 'left' || dropPosition === 'right'
  const dropIsVertical = dropPosition === 'top' || dropPosition === 'bottom'
  const dropBefore = dropPosition === 'left' || dropPosition === 'top'

  const parentIsHorizontal = parent.direction === 'horizontal'
  const parentIsVertical = parent.direction === 'vertical'

  // Direction matches parent → insert sibling
  if ((dropIsHorizontal && parentIsHorizontal) || (dropIsVertical && parentIsVertical)) {
    const insertAt = dropBefore ? index : index + 1
    parent.children.splice(insertAt, 0, slot)
    return
  }

  // Direction differs → wrap the target slot in a new nested tree
  const existing = parent.children[index] as PanelSlot
  const newDirection = dropIsHorizontal ? 'horizontal' : 'vertical'
  const children = dropBefore ? [slot, existing] : [existing, slot]
  const wrapper: PanelTree = { direction: newDirection, children }
  parent.children.splice(index, 1, wrapper)
}

/**
 * Move an existing slot to a new target. Combination of removeNode + insertAtPosition.
 * No-op if panel not found; throws if target.relativeTo is the same panel being moved.
 */
export function moveNode(
  tree: PanelTree,
  panelId: string,
  target: PanelTarget,
): void {
  if (target.relativeTo === panelId) {
    throw new Error(`[@wippy-fe/layout] cannot move panel "${panelId}" relative to itself`)
  }
  const removed = removeNode(tree, panelId)
  if (!removed)
    return
  insertAtPosition(tree, removed, target)
}

// ────────────────────────────────────────────────────────────────
// Deep clone (for immutable getLayout)
// ────────────────────────────────────────────────────────────────

/**
 * Structured clone with Vue component refs preserved by reference.
 * Used by LayoutManager.getLayout() to return a safe copy without
 * breaking Vue component identity.
 */
export function cloneLayout(decl: LayoutDeclaration): LayoutDeclaration {
  return {
    layouts: cloneLayouts(decl.layouts),
    breakpoints: decl.breakpoints ? { ...decl.breakpoints } : undefined,
    panels: clonePanels(decl.panels),
    floating: decl.floating ? cloneFloatingMap(decl.floating) : undefined,
    modals: decl.modals ? cloneModalMap(decl.modals) : undefined,
    dragEnabled: decl.dragEnabled,
  }
}

function clonePanels(panels: LayoutDeclaration['panels']): LayoutDeclaration['panels'] {
  // Deep-clone each panel def: spread the top level + deep-clone `props`
  // so callers mutating `getLayout().panels[x].props.y` cannot corrupt
  // manager state. `component` is preserved by reference (Vue components
  // can't be structurally cloned, and identity is the contract).
  const out: LayoutDeclaration['panels'] = {}
  for (const [id, def] of Object.entries(panels)) {
    out[id] = {
      ...def,
      props: def.props ? { ...def.props } : undefined,
    }
  }
  return out
}

function cloneFloatingMap(map: NonNullable<LayoutDeclaration['floating']>): NonNullable<LayoutDeclaration['floating']> {
  const out: NonNullable<LayoutDeclaration['floating']> = {}
  for (const [id, def] of Object.entries(map)) {
    out[id] = {
      ...def,
      position: { ...def.position },
      size: { ...def.size },
      minSize: def.minSize ? { ...def.minSize } : undefined,
      maxSize: def.maxSize ? { ...def.maxSize } : undefined,
      props: def.props ? { ...def.props } : undefined,
    }
  }
  return out
}

function cloneModalMap(map: NonNullable<LayoutDeclaration['modals']>): NonNullable<LayoutDeclaration['modals']> {
  const out: NonNullable<LayoutDeclaration['modals']> = {}
  for (const [id, def] of Object.entries(map)) {
    const size = def.size
    let clonedSize: typeof def.size
    if (!size) {
      clonedSize = undefined
    }
    else if ('width' in size && typeof size.width === 'string') {
      clonedSize = { ...size }
    }
    else {
      const entries: Array<[string, object]> = []
      for (const [k, v] of Object.entries(size)) {
        entries.push([k, { ...(v as object) }])
      }
      clonedSize = Object.fromEntries(entries) as typeof def.size
    }
    out[id] = {
      ...def,
      size: clonedSize,
      props: def.props ? { ...def.props } : undefined,
    }
  }
  return out
}

function cloneLayouts(layouts: Record<string, PanelTree>): LayoutDeclaration['layouts'] {
  const out: Record<string, PanelTree> = {}
  for (const [name, tree] of Object.entries(layouts)) {
    out[name] = cloneTree(tree)
  }
  return out as LayoutDeclaration['layouts']
}

function cloneTree(tree: PanelTree): PanelTree {
  return {
    ...tree,
    children: tree.children.map(c => isPanelSlot(c) ? cloneSlot(c) : cloneTree(c)),
  }
}

function cloneSlot(slot: PanelSlot): PanelSlot {
  return {
    ...slot,
    drawerSize: slot.drawerSize ? { ...slot.drawerSize } : undefined,
  }
}
