/**
 * Shared drag-state helpers used by both `LayoutSplitter` and
 * `LayoutFloating`. Implements the patterns adopted in the prior-art
 * survey (.local/2026-04-22-splitter-prior-art.md):
 *
 *   - Iframe pointer-events shield: during drag, every iframe in the
 *     document gets `pointer-events: none` via the
 *     `pointer-events-disabled` class (VS Code sash pattern). This is
 *     complemented by `setPointerCapture` on the drag handle's first
 *     `pointermove` (bvaughn's react-resizable-panels PR #693) which
 *     reroutes events past iframes directly.
 *   - Global cursor override: injects `* { cursor: X !important; }`
 *     into an adopted stylesheet so the cursor doesn't flicker when the
 *     pointer crosses child elements with a different cursor.
 *   - Teardown on `pointerup` / `pointercancel` / window `blur` — the
 *     last one covers alt-tab / focus-loss cases that VS Code's sash
 *     misses.
 *
 * All handles share a single drag-session at a time (the registry
 * guarantees this — starting a new session ends the previous one).
 */

const PE_PRIOR_KEY = '__wippyLayoutPriorPE'
let cursorStyleEl: HTMLStyleElement | null = null
let activeSession: { endFn: () => void } | null = null

function ensureCursorStyleEl(): HTMLStyleElement {
  if (cursorStyleEl)
    return cursorStyleEl
  const el = document.createElement('style')
  el.setAttribute('data-wippy-layout-cursor', '')
  document.head.appendChild(el)
  cursorStyleEl = el
  return el
}

function setGlobalCursor(cursor: string) {
  const el = ensureCursorStyleEl()
  el.textContent = `* { cursor: ${cursor} !important; }`
}

function clearGlobalCursor() {
  if (cursorStyleEl)
    cursorStyleEl.textContent = ''
}

/**
 * Collect every iframe in the document, INCLUDING those inside shadow
 * roots (`<w-artifact>` wraps its iframe in a shadow DOM, which a flat
 * `document.querySelectorAll('iframe')` doesn't see). Without piercing
 * shadow DOM the iframe shield silently fails for the most common
 * nested case in managed-layout — a splitter drag would still let
 * deeply-nested iframes intercept the pointer.
 */
function collectAllIframes(): HTMLIFrameElement[] {
  const out: HTMLIFrameElement[] = []
  function walk(root: Document | ShadowRoot) {
    for (const iframe of Array.from(root.querySelectorAll('iframe')))
      out.push(iframe as HTMLIFrameElement)
    // Open shadow roots are reachable via .shadowRoot. Closed shadow
    // roots are intentionally not addressable — accept that we don't
    // cover those (rare, deliberate by their authors).
    for (const el of Array.from(root.querySelectorAll('*'))) {
      const sr = (el as Element & { shadowRoot?: ShadowRoot | null }).shadowRoot
      if (sr)
        walk(sr)
    }
  }
  walk(document)
  return out
}

/**
 * Apply `pointer-events: none` as INLINE style. Shadow-DOM elements
 * don't inherit document-level stylesheets, so a class+CSS-rule
 * approach silently fails on iframes inside `<w-artifact>` shadow
 * roots. Inline style works regardless of host tree.
 *
 * Priors are saved on the element so we restore the original value
 * (which may itself have been "" or some author-set value) on release.
 */
function disableIframePointerEvents() {
  for (const iframe of collectAllIframes()) {
    const el = iframe as HTMLIFrameElement & { [PE_PRIOR_KEY]?: string }
    if (el[PE_PRIOR_KEY] === undefined)
      el[PE_PRIOR_KEY] = el.style.pointerEvents
    el.style.pointerEvents = 'none'
  }
}

function restoreIframePointerEvents() {
  for (const iframe of collectAllIframes()) {
    const el = iframe as HTMLIFrameElement & { [PE_PRIOR_KEY]?: string }
    const prior = el[PE_PRIOR_KEY]
    if (prior === undefined)
      continue
    el.style.pointerEvents = prior
    delete el[PE_PRIOR_KEY]
  }
}

export interface DragSessionOptions {
  cursor: string
  /** Called on every pointermove after the session starts. */
  onMove: (e: PointerEvent) => void
  /** Called on pointerup / pointercancel / window-blur / explicit end(). */
  onEnd: () => void
  /** The element that owns pointer capture (prior-art PR #693 pattern). */
  captureTarget: Element
  /** The pointerId to capture. */
  pointerId: number
}

/**
 * Start a drag session. Returns an `end()` function the caller can
 * invoke to terminate early (e.g. from an outer guard).
 *
 * Starting a second session while one is active automatically ends
 * the first — there's only ever one drag in flight.
 *
 * Pointer-capture timing: deferred to the FIRST `pointermove` per
 * react-resizable-panels PR #693. Calling `setPointerCapture` on
 * `pointerdown` occasionally misbehaves when the pointer is over a
 * child iframe on press (browsers can lose the capture if the
 * down-target element is still resolving). Letting the first move
 * confirm the drag intent and then taking capture is the pattern
 * that stuck in the open-source ecosystem.
 *
 * The iframe pointer-events shield is activated immediately so even
 * the first move is safely routed; capture is the second line of
 * defense.
 */
export function startDragSession(opts: DragSessionOptions): () => void {
  if (activeSession)
    activeSession.endFn()

  disableIframePointerEvents()
  setGlobalCursor(opts.cursor)

  let captured = false
  const handleMove = (e: PointerEvent) => {
    if (!captured) {
      captured = true
      try {
        opts.captureTarget.setPointerCapture(opts.pointerId)
      }
      catch {
        // non-captureable target (rare); document listeners still fire.
      }
    }
    opts.onMove(e)
  }

  let ended = false
  function end() {
    if (ended)
      return
    ended = true
    activeSession = null
    document.removeEventListener('pointermove', handleMove)
    document.removeEventListener('pointerup', handleEnd)
    document.removeEventListener('pointercancel', handleEnd)
    window.removeEventListener('blur', handleEnd)
    restoreIframePointerEvents()
    clearGlobalCursor()
    if (captured) {
      try {
        opts.captureTarget.releasePointerCapture(opts.pointerId)
      }
      catch {
        // already released
      }
    }
    opts.onEnd()
  }
  function handleEnd() {
    end()
  }

  // Document-level listeners catch drag-outside-window + tab-switch.
  document.addEventListener('pointermove', handleMove)
  document.addEventListener('pointerup', handleEnd)
  document.addEventListener('pointercancel', handleEnd)
  window.addEventListener('blur', handleEnd)

  activeSession = { endFn: end }
  return end
}
