<script setup lang="ts">
/**
 * Splitter between two sibling panels / nested trees. Adopts the
 * patterns from .local/2026-04-22-splitter-prior-art.md:
 *
 *   - Visible divider 1px (configurable via --wippy-layout-splitter-size).
 *     Hitbox expanded via `::before` pseudo-element with calc(50% -
 *     hover/2) centering (VS Code sash pattern).
 *   - `@media (pointer: coarse)` bumps hover size to 24px on touch —
 *     none of the reference libraries do this; Apple HIG recommends
 *     ≥24pt touch targets.
 *   - Drag uses `setPointerCapture` on the root element (bvaughn pattern,
 *     reroutes events past any iframe under the pointer) PLUS
 *     document-level move/up listeners (safety net).
 *   - Iframe shield (`pointer-events: none` on every iframe) + global
 *     cursor override are applied via the shared `drag-state` helper.
 *   - Drag resets on `pointercancel` + window `blur` (tab-switch cases
 *     VS Code's sash misses).
 *   - Adjacent nested `PanelTree` is resized via its own `flex-basis`
 *     by reading the tree's DOM bounding box; no recurse into the first
 *     leaf (matches VS Code splitview behavior).
 */

import type { LayoutManager } from './layout-manager'
import type { PanelDivider, PanelSlot, PanelTree } from './types'
import { computed, ref } from 'vue'
import { startDragSession } from './drag-state'
import { parsePixelSize, parseSize } from './helpers'

const props = defineProps<{
  direction: 'horizontal' | 'vertical'
  /** Sibling before this splitter (slot or nested tree). */
  before: PanelSlot | PanelTree | null
  /** Sibling after this splitter (slot or nested tree). */
  after: PanelSlot | PanelTree | null
  /**
   * The DOM element representing the before sibling. For a leaf slot
   * this is the slot's `<div>`; for a nested tree it's the tree's
   * container. Used to measure starting size at drag begin.
   */
  beforeEl: HTMLElement | null
  afterEl: HTMLElement | null
  /** Persistent paint only; resize hit area and semantics are unchanged. */
  paint?: PanelDivider
  manager: LayoutManager
}>()

const root = ref<HTMLDivElement | null>(null)
const dragging = ref(false)
/**
 * True while either neighbor is currently pinned at its min/max during
 * the active drag. Drives the `--clamped` visual feedback class.
 */
const clamped = ref(false)

/**
 * Reactivity tick bumped after any operation that mutates a sibling's
 * size (drag move, keyboard step, manager-driven resize via Home/End
 * collapse). `ariaValues` reads it as a dep so screen readers see the
 * new `aria-valuenow` after each step. Reads `getBoundingClientRect`
 * which is not Vue-reactive otherwise.
 */
const ariaTick = ref(0)
function refreshAria() {
  ariaTick.value++
}

// Single-pole fallback drag state (used when only one side is a resizable
// slot — the other is a nested tree or fixed). Paired drag uses the
// pairedDrag* state below.
let dragTargetId: string | null = null
let dragTargetSlot: PanelSlot | null = null
let dragStartSize = 0
let dragStartCoord = 0
let signFlip: 1 | -1 = 1

// Paired drag state — populated on pointerdown when BOTH neighbors are
// resizable slots. When set, pointermove updates both sides atomically
// via manager.resizePanelPair.
let pairedDragIdA: string | null = null
let pairedDragIdB: string | null = null
let pairedDragStartSizeA = 0
let pairedDragStartSizeB = 0
let pairedDragMinA = 0
let pairedDragMaxA = Number.POSITIVE_INFINITY
let pairedDragMinB = 0
let pairedDragMaxB = Number.POSITIVE_INFINITY

function parseMinMaxPx(value: string | undefined, _el: HTMLElement): number | null {
  // Min/max are pixel-only per the GoldenLayout-style grammar (validated
  // at decl-load by `validatePixelSize`). Anything else means the slot
  // declared no min/max and the splitter has no clamp on that side.
  return parsePixelSize(value)
}

function isSlot(node: PanelSlot | PanelTree | null): node is PanelSlot {
  return !!node && typeof (node as PanelSlot).panel === 'string'
}

function panelId(node: PanelSlot | PanelTree | null): string | undefined {
  return isSlot(node) ? node.panel : undefined
}

/**
 * Pick which side to resize. Preference order: before (if it's a
 * resizable slot), then after. For nested trees, resize the tree's
 * own container flex-basis — we synthesize a `PanelSlot`-like record
 * for the tree by assigning it the containers' current pixel size as
 * the `before`/`after` target. (A tree in the layout has no intrinsic
 * `panel` id, so for now nested-tree drag is deferred to slot-only
 * until we add tree-ids — see phase roadmap.)
 */
function pickDragTarget(): { slot: PanelSlot, sign: 1 | -1 } | null {
  if (isSlot(props.before) && !props.before.fixed && !props.before.collapsed)
    return { slot: props.before, sign: 1 }
  if (isSlot(props.after) && !props.after.fixed && !props.after.collapsed)
    return { slot: props.after, sign: -1 }
  return null
}

/**
 * Paired drag preferred when BOTH neighbors are resizable slots: one grows
 * while the other shrinks in lockstep, total stays constant, both clamp to
 * their own min/max. Falls back to single-pole drag when one side is a
 * nested tree (no panel id) or fixed.
 */
function onPointerDown(ev: PointerEvent) {
  if (ev.button !== 0)
    return
  if (!root.value)
    return

  // Try paired drag first — both sides must be resizable, non-fixed,
  // non-collapsed slots, and both DOM els must be available.
  const beforeIsResizable = isSlot(props.before) && !props.before.fixed && !props.before.collapsed
  const afterIsResizable = isSlot(props.after) && !props.after.fixed && !props.after.collapsed
  if (beforeIsResizable && afterIsResizable && props.beforeEl && props.afterEl) {
    startPairedDrag(ev, props.before as PanelSlot, props.after as PanelSlot)
    return
  }

  // Single-pole fallback (one side is a nested tree, fixed, or collapsed).
  const target = pickDragTarget()
  if (!target)
    return

  const panelEl = target.sign === 1 ? props.beforeEl : props.afterEl
  if (!panelEl)
    return

  ev.preventDefault()
  dragTargetSlot = target.slot
  dragTargetId = target.slot.panel
  signFlip = target.sign

  const rect = panelEl.getBoundingClientRect()
  dragStartSize = props.direction === 'horizontal' ? rect.width : rect.height
  dragStartCoord = props.direction === 'horizontal' ? ev.clientX : ev.clientY

  dragging.value = true
  startDragSession({
    cursor: props.direction === 'horizontal' ? 'col-resize' : 'row-resize',
    captureTarget: root.value,
    pointerId: ev.pointerId,
    onMove: (e) => {
      if (!dragTargetId || !dragTargetSlot)
        return
      const coord = props.direction === 'horizontal' ? e.clientX : e.clientY
      const delta = coord - dragStartCoord
      let nextSize = Math.max(0, dragStartSize + delta * signFlip)
      const min = parseMinMaxPx(dragTargetSlot.minSize, panelEl)
      if (min !== null)
        nextSize = Math.max(nextSize, min)
      const max = parseMinMaxPx(dragTargetSlot.maxSize, panelEl)
      if (max !== null)
        nextSize = Math.min(nextSize, max)
      props.manager.resizePanel(dragTargetId, `${Math.round(nextSize)}px`)
      refreshAria()
    },
    onEnd: () => {
      dragging.value = false
      dragTargetId = null
      dragTargetSlot = null
    },
  })
}

function startPairedDrag(ev: PointerEvent, slotA: PanelSlot, slotB: PanelSlot) {
  if (!root.value || !props.beforeEl || !props.afterEl)
    return

  ev.preventDefault()

  const isHorizontal = props.direction === 'horizontal'
  const rectA = props.beforeEl.getBoundingClientRect()
  const rectB = props.afterEl.getBoundingClientRect()

  pairedDragIdA = slotA.panel
  pairedDragIdB = slotB.panel
  pairedDragStartSizeA = isHorizontal ? rectA.width : rectA.height
  pairedDragStartSizeB = isHorizontal ? rectB.width : rectB.height

  // Parse min/max for both sides at drag-start. `parseMinMaxPx` may need the
  // element to resolve `%` against parent — pass the corresponding side's el.
  const minA = parseMinMaxPx(slotA.minSize, props.beforeEl)
  const maxA = parseMinMaxPx(slotA.maxSize, props.beforeEl)
  const minB = parseMinMaxPx(slotB.minSize, props.afterEl)
  const maxB = parseMinMaxPx(slotB.maxSize, props.afterEl)
  pairedDragMinA = minA ?? 0
  pairedDragMaxA = maxA ?? Number.POSITIVE_INFINITY
  pairedDragMinB = minB ?? 0
  pairedDragMaxB = maxB ?? Number.POSITIVE_INFINITY

  dragStartCoord = isHorizontal ? ev.clientX : ev.clientY
  dragging.value = true
  clamped.value = false

  const total = pairedDragStartSizeA + pairedDragStartSizeB

  // If a neighbor's declared size is `Nfr`, it's the "absorber" — it
  // grows/shrinks via flex to fill remaining space, and we MUST NOT
  // overwrite its size with a px value during drag, or it loses its
  // flex-grow and the row redistributes weirdly (siblings expand into
  // the space the actor freed). Identify the fr side via the parsed
  // size grammar (NOT string-suffix sniffing — `parseSize` is the
  // canonical unit dispatcher; values outside the whitelist are caught
  // at validateLayout time). Both-fr and both-non-fr cases fall back
  // to the constant-sum paired write.
  const aIsFr = parseSize(slotA.size)?.unit === 'fr'
  const bIsFr = parseSize(slotB.size)?.unit === 'fr'

  startDragSession({
    cursor: isHorizontal ? 'col-resize' : 'row-resize',
    captureTarget: root.value,
    pointerId: ev.pointerId,
    onMove: (e) => {
      if (!pairedDragIdA || !pairedDragIdB)
        return

      const coord = isHorizontal ? e.clientX : e.clientY
      const delta = coord - dragStartCoord

      // Tentative split: A grows by delta, B shrinks by delta.
      let nextA = pairedDragStartSizeA + delta
      let nextB = pairedDragStartSizeB - delta

      let didClamp = false

      // A-side clamps. When A pins, recompute B from the constant-sum
      // invariant so the splitter never "leaves a gap".
      if (nextA < pairedDragMinA) {
        nextA = pairedDragMinA
        nextB = total - nextA
        didClamp = true
      }
      else if (nextA > pairedDragMaxA) {
        nextA = pairedDragMaxA
        nextB = total - nextA
        didClamp = true
      }

      // B-side clamps. May override A's clamp result — that's fine because
      // both clamps acting at once means A is also at its limit (the only
      // way both fire in one frame is when total < minA + minB or total >
      // maxA + maxB, which is a layout misconfiguration; we still leave the
      // pair in a valid state by honoring B's clamp last).
      if (nextB < pairedDragMinB) {
        nextB = pairedDragMinB
        nextA = total - nextB
        didClamp = true
      }
      else if (nextB > pairedDragMaxB) {
        nextB = pairedDragMaxB
        nextA = total - nextB
        didClamp = true
      }

      clamped.value = didClamp

      // Write strategy depends on which sides are flex-grow. When exactly
      // one side is `1fr`, only update the FIXED side — the fr side
      // absorbs via flex automatically. When both are fixed, do a true
      // paired write. Both-fr is rare (and the default flex math handles
      // it natively); fall through to paired write so the user still
      // gets feedback. Round here because resizePanel/resizePanelPair
      // store stringified px.
      const a = Math.round(nextA)
      const b = Math.round(nextB)
      if (aIsFr && !bIsFr)
        props.manager.resizePanel(pairedDragIdB, `${b}px`)
      else if (bIsFr && !aIsFr)
        props.manager.resizePanel(pairedDragIdA, `${a}px`)
      else
        props.manager.resizePanelPair(pairedDragIdA, a, pairedDragIdB, b)

      refreshAria()
    },
    onEnd: () => {
      dragging.value = false
      clamped.value = false
      pairedDragIdA = null
      pairedDragIdB = null
    },
  })
}

function onDoubleClick() {
  const slot = isSlot(props.before)
    ? props.before
    : isSlot(props.after) ? props.after : null
  if (!slot?.collapsible)
    return
  if (slot.collapsed) {
    props.manager.expandPanel(slot.panel)
  }
  else {
    props.manager.collapsePanel(slot.panel)
  }
  refreshAria()
}

const canDrag = computed(() => !!pickDragTarget())

/**
 * Live ARIA values for the resize-target sibling. Re-evaluates when
 * `ariaTick` bumps (after drag / keyboard step / collapse) — reads
 * `getBoundingClientRect` which Vue doesn't auto-track. Returns null
 * when there's no resizable side (locked splitter); template binds
 * `null` / `undefined` to omit the aria attribute.
 */
const ariaValues = computed<{ now: number, min?: number, max?: number } | null>(() => {
  // eslint-disable-next-line ts/no-unused-expressions
  ariaTick.value
  const target = pickDragTarget()
  if (!target)
    return null
  const el = target.sign === 1 ? props.beforeEl : props.afterEl
  if (!el)
    return null
  const rect = el.getBoundingClientRect()
  const size = props.direction === 'horizontal' ? rect.width : rect.height
  const min = parseMinMaxPx(target.slot.minSize, el)
  const max = parseMinMaxPx(target.slot.maxSize, el)
  return {
    now: Math.round(size),
    min: min !== null ? Math.round(min) : undefined,
    max: max !== null ? Math.round(max) : undefined,
  }
})

/**
 * Keyboard resize. Mirrors the drag math sign convention so screen-reader
 * users get the same outcome as mouse drag:
 *   - Arrow toward the target side shrinks it; opposite arrow grows it.
 *   - Step = 8px (Shift = 32px) per AC §5.2.
 *   - Home: collapse if `collapsible: true`, else clamp to minSize.
 *   - End: clamp to maxSize (no max → grow as much as platform allows;
 *     parent flex will absorb any excess request via the manager).
 *
 * Only the matching axis arrows respond — horizontal splitters react to
 * Left/Right; vertical to Up/Down. Off-axis arrows fall through to default
 * browser behavior (no interception, no scroll suppression).
 */
function onKeyDown(ev: KeyboardEvent) {
  const target = pickDragTarget()
  if (!target)
    return

  const isHorizontal = props.direction === 'horizontal'
  let arrowDelta = 0
  if (isHorizontal) {
    if (ev.key === 'ArrowLeft')
      arrowDelta = -1
    else if (ev.key === 'ArrowRight')
      arrowDelta = +1
  }
  else {
    if (ev.key === 'ArrowUp')
      arrowDelta = -1
    else if (ev.key === 'ArrowDown')
      arrowDelta = +1
  }
  const isHomeEnd = ev.key === 'Home' || ev.key === 'End'
  if (arrowDelta === 0 && !isHomeEnd)
    return

  ev.preventDefault()
  ev.stopPropagation()

  const slot = target.slot
  const el = target.sign === 1 ? props.beforeEl : props.afterEl
  if (!el)
    return

  const rect = el.getBoundingClientRect()
  const currentSize = isHorizontal ? rect.width : rect.height

  let nextSize = currentSize

  if (ev.key === 'Home') {
    if (slot.collapsible) {
      props.manager.collapsePanel(slot.panel)
      refreshAria()
      return
    }
    nextSize = 0 // clamped to minSize below
  }
  else if (ev.key === 'End') {
    nextSize = Number.MAX_SAFE_INTEGER // clamped to maxSize below; parent absorbs the rest
  }
  else {
    const step = ev.shiftKey ? 32 : 8
    nextSize = currentSize + arrowDelta * step * target.sign
  }

  const min = parseMinMaxPx(slot.minSize, el)
  if (min !== null)
    nextSize = Math.max(nextSize, min)
  const max = parseMinMaxPx(slot.maxSize, el)
  if (max !== null)
    nextSize = Math.min(nextSize, max)

  nextSize = Math.max(0, Math.round(nextSize))
  props.manager.resizePanel(slot.panel, `${nextSize}px`)
  refreshAria()
}

function onFocus() {
  refreshAria()
}
</script>

<template>
  <div
    ref="root"
    class="wippy-layout-splitter"
    :class="[
      `wippy-layout-splitter--${direction}`,
      dragging && 'wippy-layout-splitter--dragging',
      clamped && 'wippy-layout-splitter--clamped',
      !canDrag && 'wippy-layout-splitter--locked',
      `wippy-layout-splitter--paint-${paint ?? 'default'}`,
    ]"
    :data-direction="direction"
    :data-before-panel="panelId(before)"
    :data-after-panel="panelId(after)"
    role="separator"
    :aria-orientation="direction === 'horizontal' ? 'vertical' : 'horizontal'"
    :tabindex="canDrag ? 0 : -1"
    :aria-disabled="canDrag ? undefined : true"
    :aria-valuenow="ariaValues?.now"
    :aria-valuemin="ariaValues?.min"
    :aria-valuemax="ariaValues?.max"
    @pointerdown="onPointerDown"
    @dblclick="onDoubleClick"
    @keydown="onKeyDown"
    @focus="onFocus"
  >
    <span class="wippy-layout-splitter__handle" aria-hidden="true">
      <svg width="11" height="11" viewBox="0 0 24 24" focusable="false">
        <path
          fill="none"
          stroke="currentColor"
          stroke-linecap="round"
          stroke-linejoin="round"
          stroke-width="2"
          d="M7 8l-4 4l4 4M17 8l4 4l-4 4"
        />
      </svg>
    </span>
  </div>
</template>

<style scoped>
/*
 * 1px visible divider + widened ::before hitbox. The divider itself is
 * semi-transparent, barely visible; on hover / drag it lights up. The
 * hitbox (below) extends ±4px (mouse) or ±12px (touch) past the visible
 * bar so the pointer reliably grabs without the user seeing a thick
 * splitter.
 */
.wippy-layout-splitter {
  position: relative;
  flex-shrink: 0;
  background: var(--wippy-layout-splitter-bg, transparent);
  touch-action: none;
  user-select: none;
  /*
   * The manager root isolates this layer. Keep splitters above ordinary
   * panel-local chrome while remaining below managed drawers/backdrops
   * (800+) and open drawer content (901).
   */
  z-index: var(--wippy-layout-splitter-z-index, 700);
}
/*
 * Hit area: a transparent absolutely-positioned ::before that extends
 * past the visible 1px bar. Default 10px (5px each side) — configurable
 * via `--wippy-layout-splitter-hit-size`. Visual remains the parent's
 * width/height (1px); the ::before only handles pointer aim.
 *
 * Stacking: NO `z-index: -1`. With z-index: -1 the hitbox slips behind
 * sibling panels' interactive content and the cursor lands on iframes /
 * web components instead of the splitter — "impossible to aim". Default
 * stack (auto) keeps the hitbox in the splitter's painted layer, which
 * sits above sibling panels because the splitter itself is z-index: 1.
 */
.wippy-layout-splitter::before {
  content: '';
  position: absolute;
  /* No z-index — keep the hitbox in the splitter's stacking layer. */
}
.wippy-layout-splitter--horizontal {
  width: var(--wippy-layout-splitter-size, 1px);
  cursor: col-resize;
}
.wippy-layout-splitter--horizontal::before {
  top: 0;
  bottom: 0;
  left: calc(50% - var(--wippy-layout-splitter-hit-size, 10px) / 2);
  width: var(--wippy-layout-splitter-hit-size, 10px);
}
.wippy-layout-splitter--vertical {
  height: var(--wippy-layout-splitter-size, 1px);
  cursor: row-resize;
}
.wippy-layout-splitter--vertical::before {
  left: 0;
  right: 0;
  top: calc(50% - var(--wippy-layout-splitter-hit-size, 10px) / 2);
  height: var(--wippy-layout-splitter-hit-size, 10px);
}
/*
 * Optional grab handle. Third-party consumers opt in through custom
 * properties; the element is separate from `::before`, which remains the
 * expanded pointer hit area. When enabled, the handle is revealed on hover,
 * drag, and focus.
 */
.wippy-layout-splitter__handle {
  position: absolute;
  display: grid;
  place-items: center;
  width: var(--wippy-layout-splitter-handle-size, 0);
  height: var(--wippy-layout-splitter-handle-size, 0);
  border-radius: 50%;
  background: var(--wippy-layout-splitter-handle-bg, transparent);
  border: var(--wippy-layout-splitter-handle-border, 0 solid transparent);
  box-shadow: var(--wippy-layout-splitter-handle-shadow, none);
  color: var(--wippy-layout-splitter-handle-icon-color, transparent);
  opacity: 0;
  transition: opacity 120ms ease-in-out;
  pointer-events: none;
}
.wippy-layout-splitter__handle svg {
  display: block;
}
.wippy-layout-splitter--horizontal .wippy-layout-splitter__handle {
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.wippy-layout-splitter--vertical .wippy-layout-splitter__handle {
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(90deg);
}
.wippy-layout-splitter:not(.wippy-layout-splitter--locked):hover .wippy-layout-splitter__handle,
.wippy-layout-splitter--dragging .wippy-layout-splitter__handle,
.wippy-layout-splitter:focus-visible .wippy-layout-splitter__handle {
  opacity: 1;
}
/* A locked splitter cannot be dragged, so advertising a grab point lies. */
.wippy-layout-splitter--locked .wippy-layout-splitter__handle {
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  .wippy-layout-splitter__handle {
    transition: none;
  }
}

/* Visible line lights up on hover / drag / keyboard focus */
.wippy-layout-splitter:not(.wippy-layout-splitter--locked):hover,
.wippy-layout-splitter--dragging,
.wippy-layout-splitter:focus-visible {
  background: var(--wippy-layout-splitter-hover-bg, rgba(0, 0, 0, 0.25));
}
/*
 * Clamped state: at least one side hit its min/max during the active drag.
 * Overrides hover/dragging tints. Uses `&` doubling for specificity so it
 * beats the multi-selector hover rule above without `!important`.
 */
.wippy-layout-splitter.wippy-layout-splitter--clamped,
.wippy-layout-splitter.wippy-layout-splitter--clamped:hover,
.wippy-layout-splitter.wippy-layout-splitter--clamped.wippy-layout-splitter--dragging {
  background: var(--wippy-layout-splitter-clamped-bg, rgba(255, 165, 0, 0.55));
}
/*
 * Suppress the default focus ring on click; only show on keyboard focus.
 * The 2px outline + 1px offset reads as a 4-5px halo around the 1px line —
 * subtle but discoverable.
 */
.wippy-layout-splitter:focus {
  outline: none;
}
.wippy-layout-splitter:focus-visible {
  outline: 2px solid var(--wippy-layout-splitter-focus, currentColor);
  outline-offset: 1px;
}
.wippy-layout-splitter--locked {
  cursor: default;
  pointer-events: none;
}
.wippy-layout-splitter--paint-line:not(:hover):not(.wippy-layout-splitter--dragging):not(.wippy-layout-splitter--clamped) {
  background: var(--wippy-layout-boundary-color, var(--p-surface-200, #e5e7eb));
}
.wippy-layout-splitter--paint-none:not(:hover):not(.wippy-layout-splitter--dragging):not(.wippy-layout-splitter--clamped) {
  background: transparent;
}
/*
 * A paint-free boundary must not expose the manager canvas as a 1px strip
 * between differently layered panel surfaces. Keep the splitter's physical
 * box for pointer, keyboard-focus and hover paint, but remove that box from
 * flex sizing so the following panel paints underneath it. Default and line
 * dividers retain their existing layout thickness.
 */
.wippy-layout-splitter--paint-none.wippy-layout-splitter--horizontal {
  margin-inline-end: calc(-1 * var(--wippy-layout-splitter-size, 1px));
}
.wippy-layout-splitter--paint-none.wippy-layout-splitter--vertical {
  margin-block-end: calc(-1 * var(--wippy-layout-splitter-size, 1px));
}
/* Touch: bump hitbox to 24px for comfortable grabbing (Apple HIG ≥24pt). */
@media (pointer: coarse) {
  .wippy-layout-splitter--horizontal::before,
  .wippy-layout-splitter--vertical::before {
    --wippy-layout-splitter-hit-size: 24px;
  }
}
</style>
