<script setup lang="ts">
/**
 * Native-dialog modal. Uses `<dialog showModal()>` for:
 *
 *   - Top-layer stacking (AC §5.11) — the dialog paints above everything
 *     in the host's normal z-index space, including iframes, popovers,
 *     and CSS transforms / containing blocks. No `z-index: 99999` arms
 *     race; the browser picks.
 *   - Built-in focus trap (AC §5.7, §5.12) — Tab cycles inside the
 *     dialog only; focus is restored to the previously-focused element
 *     when the dialog closes.
 *   - `inert` propagation — every other element under `<html>` becomes
 *     non-interactive while the dialog is open. No need to manually
 *     toggle `aria-hidden` on the layout root.
 *   - Native `cancel` event for ESC. Honors `dismissable: false` by
 *     `preventDefault()`-ing the cancel.
 *   - `::backdrop` pseudo-element for the dimmed overlay — styled via
 *     scoped CSS below.
 *
 * Stacking of multiple modals is the browser's responsibility — each
 * `showModal()` pushes onto the top-layer stack; closing any modal
 * pops it. Background interaction stays inert.
 *
 * The legacy `LayoutModal.vue` (div-overlay implementation) remains
 * available for one minor release behind `def.useNativeDialog === false`
 * — see types.ts. Default is native.
 */

import type { LayoutManager } from './layout-manager'
import type { ModalDef } from './types'
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useAttentionElement } from './attention-element'
import { useLayoutBreakpoint } from './composables'
import { resolveModalDialogStyle } from './helpers'
import PanelSlotContext from './PanelSlotContext.vue'

const props = defineProps<{
  id: string
  def: ModalDef
  manager: LayoutManager
  stackIndex: number
  attentionElement?: (element: HTMLElement | null) => void
}>()

const dialogEl = ref<HTMLDialogElement | null>(null)
useAttentionElement(dialogEl, () => props.attentionElement)
const dismissable = computed(() => props.def.dismissable !== false)
const activeBreakpoint = useLayoutBreakpoint(props.manager)

const dialogStyle = computed<Record<string, string>>(() =>
  resolveModalDialogStyle(props.def.size, activeBreakpoint.value),
)

/**
 * Open via `showModal()`. MUST run after the element is connected to
 * the document (`onMounted` fires post-mount), otherwise Chrome throws
 * `InvalidStateError: dialog is not connected`.
 *
 * If `showModal` doesn't exist (very old browsers, JSDOM), close the
 * modal immediately so the manager doesn't think it's open. The
 * caller is expected to feature-flag back to LayoutModal in that
 * environment via `useNativeDialog: false`, but we shouldn't loop if
 * they didn't.
 */
function openDialog() {
  const el = dialogEl.value
  if (!el)
    return
  if (typeof el.showModal !== 'function') {
    // Platform doesn't support <dialog>. Bail out cleanly.
    props.manager.closeModal(props.id)
    return
  }
  if (!el.open)
    el.showModal()
}

/**
 * `cancel` fires on ESC key. Default action is to close the dialog;
 * we either let it through (dismissable) or `preventDefault()` to
 * keep the modal open. We do NOT call `closeModal` here — the dialog
 * will fire `close` next and the close handler routes through the
 * manager.
 */
function onCancel(e: Event) {
  if (!dismissable.value)
    e.preventDefault()
}

/**
 * `close` fires when the dialog actually closes (after cancel has run
 * and not been preventDefault'd, or after `el.close()` is called
 * imperatively). Route through the manager so subscribers see a single
 * canonical close event regardless of source (ESC, backdrop click,
 * close button, programmatic).
 *
 * Guard against re-entry: `closeModal` removes the modal from the
 * manager's set, which un-mounts THIS component. If we're un-mounting
 * because of a programmatic close (e.g. another component called
 * `manager.closeModal(id)`), `el.open` is already false and we should
 * not call `closeModal` again — that would no-op but adds an event
 * spam. The `closingFromManager` flag tracks this.
 */
let closingFromManager = false
function onClose() {
  if (closingFromManager)
    return
  props.manager.closeModal(props.id)
}

/**
 * Backdrop click detection. `<dialog>` doesn't expose a backdrop event
 * directly, but a click event whose `target === dialogEl` fired BECAUSE
 * the click landed on the backdrop area (the dialog itself is the
 * element above the ::backdrop; descendant elements would be the
 * actual `target`). Common pattern across the dialog community.
 *
 * Only honored when `dismissable: true`; matches the ESC policy.
 */
function onClick(e: MouseEvent) {
  if (!dismissable.value)
    return
  if (e.target === dialogEl.value)
    dialogEl.value?.close('backdrop-click')
}

/**
 * Programmatic close from the title-bar X button. Manually drive the
 * close so `cancel` doesn't fire (cancel is ESC-specific in spec).
 */
function closeFromButton() {
  if (!dismissable.value)
    return
  dialogEl.value?.close('close-button')
}

onMounted(() => {
  openDialog()
})

/**
 * If the manager closes us programmatically (e.g. another component
 * calls `closeModal(id)`), this component starts un-mounting before
 * the dialog naturally fires `close`. Imperatively close the element
 * so the browser releases the top-layer slot and restores focus to
 * the opener; flag the close so `onClose` doesn't loop back into the
 * manager.
 */
onBeforeUnmount(() => {
  const el = dialogEl.value
  if (!el)
    return
  if (el.open) {
    closingFromManager = true
    el.close('manager-close')
  }
})

// Note: `def.useNativeDialog` flipping at runtime is handled at the
// dispatcher level in LayoutManagerView — `<component :is>` swaps the
// component identity which Vue treats as a remount, so this component
// has nothing to react to. No watch needed.
</script>

<template>
  <dialog
    ref="dialogEl"
    class="wippy-layout-modal-native"
    :aria-label="def.title ?? id"
    :style="dialogStyle"
    :data-stack-index="stackIndex"
    @cancel="onCancel"
    @close="onClose"
    @click="onClick"
  >
    <header v-if="def.title" class="wippy-layout-modal-native__header">
      <span class="wippy-layout-modal-native__title">{{ def.title }}</span>
      <button
        v-if="dismissable"
        class="wippy-layout-modal-native__close"
        type="button"
        aria-label="Close"
        @click="closeFromButton"
      >
        ×
      </button>
    </header>
    <div class="wippy-layout-modal-native__content">
      <!--
        `:panel-id="id"` flows the modal id through `PanelSlotContext`
        → `wirePanelContext` → `el.dataset.wippyPanelId`. Modal bodies
        read it via `usePanelId()` from `@wippy-fe/webcomponent-vue`
        and echo it back in their close broadcast — no extra wiring
        on this template.
      -->
      <PanelSlotContext :panel-id="id" :tree="{ direction: 'vertical', children: [] }" :manager="manager">
        <component :is="def.component" v-bind="def.props ?? {}" />
      </PanelSlotContext>
    </div>
  </dialog>
</template>

<style scoped>
.wippy-layout-modal-native {
  /*
   * Reset UA defaults that interfere with our layout system: most UAs
   * give <dialog> a 1px border, ~1em padding, fit-content sizing, and
   * `position: fixed` with hardcoded inset. We override sizing
   * explicitly via inline `dialogStyle` (width/height/maxWidth) and
   * keep the dialog centered via `margin: auto` (browser default for
   * top-layer dialogs already).
   */
  border: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  background: var(--wippy-layout-modal-bg, #fff);
  color: var(--wippy-layout-modal-fg, inherit);
  border-radius: 8px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  /* overflow visible per AC §5.1 — popovers / tooltips inside the modal
   * need to escape the modal box (e.g. a date picker rendering above
   * its input field). The native dialog doesn't enforce overflow. */
  overflow: visible;
}
.wippy-layout-modal-native::backdrop {
  /* The native ::backdrop is the pseudo-element behind the dialog.
   * Styled identically to the legacy div-overlay backdrop. Honors
   * prefers-reduced-motion via the @media block below. */
  background: var(--wippy-layout-modal-backdrop, rgba(0, 0, 0, 0.45));
}
@media (prefers-reduced-motion: no-preference) {
  .wippy-layout-modal-native[open] {
    animation: wippy-layout-modal-native-in 200ms ease;
  }
  .wippy-layout-modal-native::backdrop {
    animation: wippy-layout-modal-native-backdrop-in 200ms ease;
  }
  @keyframes wippy-layout-modal-native-in {
    from { opacity: 0; transform: scale(0.96); }
    to { opacity: 1; transform: scale(1); }
  }
  @keyframes wippy-layout-modal-native-backdrop-in {
    from { opacity: 0; }
    to { opacity: 1; }
  }
}
.wippy-layout-modal-native__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--wippy-layout-border-color, rgba(0, 0, 0, 0.08));
  font: 600 0.9375rem/1.2 system-ui, sans-serif;
}
.wippy-layout-modal-native__title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wippy-layout-modal-native__close {
  background: none;
  border: none;
  font-size: 1.5rem;
  line-height: 1;
  padding: 0 0.25rem;
  cursor: pointer;
  color: inherit;
  opacity: 0.6;
}
.wippy-layout-modal-native__close:hover {
  opacity: 1;
}
.wippy-layout-modal-native__content {
  flex: 1 1 auto;
  overflow: auto;
  padding: 1rem;
}
</style>
