<script setup lang="ts">
/**
 * @deprecated Use `LayoutModalNative` (the default since v1.1). This
 * div-overlay implementation is kept for one minor release as a
 * fallback for platforms without `HTMLDialogElement.showModal` (very
 * old browsers, JSDOM) and for consumers who explicitly opt out via
 * `ModalDef.useNativeDialog: false`. It will be removed in the next
 * major.
 *
 * Why deprecated: the platform's native `<dialog showModal()>` provides
 * top-layer stacking (AC §5.11), focus trap (§5.7, §5.12), `inert`
 * propagation, and a native ::backdrop pseudo-element for free —
 * matching all of which manually requires a JS focus-trap, an
 * `aria-hidden` toggle on the layout root, and a z-index arms race
 * against page popovers. See `LayoutModalNative.vue` for the
 * replacement.
 *
 * Original v1 contract preserved: backdrop, ESC close (unless
 * `dismissable: false`), backdrop-click close, z-index stacking via
 * `stackIndex`. Focus trap was deferred — browsers cycle focus
 * naturally via Tab; the behavior is correct but not trapped inside
 * the dialog. The native version closes that gap.
 *
 * ESC-closes-topmost-only behavior is backed by `modal-stack.ts`, which
 * tracks currently-mounted modals at module scope (required — SFC
 * `<script setup>` locals are per-instance).
 */

import type { LayoutManager } from './layout-manager'
import type { ModalDef } from './types'
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useAttentionElement } from './attention-element'
import { useLayoutBreakpoint } from './composables'
import { resolveModalDialogStyle } from './helpers'
import { registerMountedModal, topmostStackIndex, unregisterMountedModal } from './modal-stack'
import PanelSlotContext from './PanelSlotContext.vue'

const props = defineProps<{
  id: string
  def: ModalDef
  manager: LayoutManager
  stackIndex: number
  attentionElement?: (element: HTMLElement | null) => void
}>()

const attentionRoot = ref<HTMLElement | null>(null)
useAttentionElement(attentionRoot, () => props.attentionElement)

const dismissable = computed(() => props.def.dismissable !== false)
const activeBreakpoint = useLayoutBreakpoint(props.manager)

const dialogStyle = computed<Record<string, string>>(() =>
  resolveModalDialogStyle(props.def.size, activeBreakpoint.value),
)

const backdropStyle = computed<Record<string, string>>(() => ({
  zIndex: String(2000 + props.stackIndex),
}))

function close() {
  if (!dismissable.value)
    return
  props.manager.closeModal(props.id)
}

function onBackdropClick() {
  close()
}

function onKey(e: KeyboardEvent) {
  if (e.key !== 'Escape')
    return
  if (props.stackIndex < topmostStackIndex())
    return
  e.stopPropagation()
  close()
}

// stackIndex comes from the v-for position in LayoutManagerView and
// CAN change without the component re-mounting (when a modal earlier
// in the list closes, siblings shift down). Watch for that and keep
// the module-level registry in sync.
let registered: number | null = null
function register(next: number) {
  if (registered === next)
    return
  if (registered !== null)
    unregisterMountedModal(registered)
  registerMountedModal(next)
  registered = next
}
watch(() => props.stackIndex, register, { immediate: false })

onMounted(() => {
  register(props.stackIndex)
  window.addEventListener('keydown', onKey)
})

onBeforeUnmount(() => {
  if (registered !== null) {
    unregisterMountedModal(registered)
    registered = null
  }
  window.removeEventListener('keydown', onKey)
})
</script>

<template>
  <div
    class="wippy-layout-modal-backdrop"
    :style="backdropStyle"
    @click.self="onBackdropClick"
  >
    <div
      ref="attentionRoot"
      class="wippy-layout-modal"
      role="dialog"
      aria-modal="true"
      :aria-label="def.title ?? id"
      :style="dialogStyle"
      tabindex="-1"
    >
      <header v-if="def.title" class="wippy-layout-modal__header">
        <span class="wippy-layout-modal__title">{{ def.title }}</span>
        <button
          v-if="dismissable"
          class="wippy-layout-modal__close"
          type="button"
          aria-label="Close"
          @click="close"
        >
          ×
        </button>
      </header>
      <div class="wippy-layout-modal__content">
        <PanelSlotContext :panel-id="id" :tree="{ direction: 'vertical', children: [] }" :manager="manager">
          <component :is="def.component" v-bind="def.props ?? {}" />
        </PanelSlotContext>
      </div>
    </div>
  </div>
</template>

