<script setup lang="ts">
/**
 * Absolute-positioned floating window. Draggable via header; resizable
 * via 8 grip handles (4 corners + 4 edges) adopting the prior-art
 * pattern from re-resizable + VS Code sash. Pointer-events shield on
 * iframes during drag so nested iframes don't swallow events; global
 * cursor override via the shared `drag-state` helper.
 *
 * Keyboard accessibility — none of the reference libraries ship
 * arrow-key resize; TODO once we see a concrete need.
 */

import type { LayoutManager } from './layout-manager'
import type { FloatingPanelDef } from './types'
import { computed, ref, watch } from 'vue'
import { useAttentionElement } from './attention-element'
import { startDragSession } from './drag-state'
import PanelSlotContext from './PanelSlotContext.vue'
import { panelAnchorName } from './types'

type GripKind = 'move' | 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw'

const props = defineProps<{
  id: string
  def: FloatingPanelDef
  manager: LayoutManager
  stackIndex: number
  attentionElement?: (element: HTMLElement | null) => void
}>()

const root = ref<HTMLDivElement | null>(null)
useAttentionElement(root, () => props.attentionElement)
const dragging = ref(false)

// Local refs so we can stream smooth updates during drag WITHOUT paying
// the reactive-subscription cost; we commit to the manager once on
// pointerup.
const x = ref(props.def.position.x)
const y = ref(props.def.position.y)
const w = ref(props.def.size.width)
const h = ref(props.def.size.height)

const MIN_VISIBLE = 40

function clampPosition(px: number, py: number, width: number, _height: number) {
  const maxX = window.innerWidth - MIN_VISIBLE
  const maxY = window.innerHeight - MIN_VISIBLE
  const minX = -(width - MIN_VISIBLE)
  const minY = 0
  return {
    x: Math.max(minX, Math.min(maxX, px)),
    y: Math.max(minY, Math.min(maxY, py)),
  }
}

function clampSize(width: number, height: number) {
  const minW = props.def.minSize?.width ?? 160
  const minH = props.def.minSize?.height ?? 100
  const maxW = props.def.maxSize?.width ?? window.innerWidth
  const maxH = props.def.maxSize?.height ?? window.innerHeight
  return {
    width: Math.max(minW, Math.min(maxW, width)),
    height: Math.max(minH, Math.min(maxH, height)),
  }
}

function cursorFor(kind: GripKind): string {
  switch (kind) {
    case 'move': return 'grabbing'
    case 'n':
    case 's': return 'ns-resize'
    case 'e':
    case 'w': return 'ew-resize'
    case 'ne':
    case 'sw': return 'nesw-resize'
    case 'nw':
    case 'se': return 'nwse-resize'
  }
}

function beginDrag(ev: PointerEvent, kind: GripKind) {
  if (ev.button !== 0)
    return
  const handle = ev.currentTarget as HTMLElement
  ev.preventDefault()
  ev.stopPropagation()

  const startX = x.value
  const startY = y.value
  const startW = w.value
  const startH = h.value
  const startPointerX = ev.clientX
  const startPointerY = ev.clientY

  dragging.value = true

  startDragSession({
    cursor: cursorFor(kind),
    captureTarget: handle,
    pointerId: ev.pointerId,
    onMove: (e) => {
      const dx = e.clientX - startPointerX
      const dy = e.clientY - startPointerY
      let nextX = startX
      let nextY = startY
      let nextW = startW
      let nextH = startH

      if (kind === 'move') {
        nextX = startX + dx
        nextY = startY + dy
      }
      else {
        if (kind === 'e' || kind === 'ne' || kind === 'se')
          nextW = startW + dx
        if (kind === 'w' || kind === 'nw' || kind === 'sw') {
          nextW = startW - dx
          nextX = startX + dx
        }
        if (kind === 's' || kind === 'se' || kind === 'sw')
          nextH = startH + dy
        if (kind === 'n' || kind === 'ne' || kind === 'nw') {
          nextH = startH - dy
          nextY = startY + dy
        }
        const sz = clampSize(nextW, nextH)
        // Compensate origin when clamping pulled a west/north edge: keep
        // the opposite edge visually pinned.
        if (kind === 'w' || kind === 'nw' || kind === 'sw')
          nextX = startX + startW - sz.width
        if (kind === 'n' || kind === 'ne' || kind === 'nw')
          nextY = startY + startH - sz.height
        nextW = sz.width
        nextH = sz.height
      }

      const pos = clampPosition(nextX, nextY, nextW, nextH)
      x.value = pos.x
      y.value = pos.y
      w.value = nextW
      h.value = nextH
    },
    onEnd: () => {
      dragging.value = false
      props.manager.updateFloating(props.id, {
        position: { x: x.value, y: y.value },
        size: { width: w.value, height: h.value },
      })
    },
  })
}

function onClose() {
  props.manager.removeFloating(props.id)
}

function onFocusToTop() {
  // Bare flaps don't participate in click-to-front z-stacking — they're
  // pinned chrome, not windows. (The handler is on the root, not the
  // header, so skipping the header alone wouldn't stop this.)
  if (props.def.chrome === false)
    return
  // Fix: `(zIndex ?? 1000) + stackIndex + 1` — not `zIndex ?? (1000 + stackIndex) + 1`.
  props.manager.updateFloating(props.id, {
    zIndex: (props.def.zIndex ?? 1000) + props.stackIndex + 1,
  })
}

/** `12` → `'12px'`; any string passes through so `'50%'` / `'2rem'` work. */
function cssLength(v: number | string): string {
  return typeof v === 'number' ? `${v}px` : v
}

// `chrome: false` ⇒ bare flap: no header/close/grips/drag/border. The
// content fills the box and may overflow it (edge chevron + hover menu).
const chrome = computed(() => props.def.chrome !== false)

/**
 * Resolve the anchor to CSS offsets, or `null` when it does not apply.
 *
 * Ignored for panels with chrome: those are user-draggable and dragging
 * writes absolute `position`, so an anchor would fight the user's own
 * drag on the next render.
 */
const anchorStyle = computed<Record<string, string> | null>(() => {
  const a = props.def.anchor
  if (!a || chrome.value)
    return null
  const out: Record<string, string> = {}
  if (a.top !== undefined)
    out.top = cssLength(a.top)
  if (a.right !== undefined)
    out.right = cssLength(a.right)
  if (a.bottom !== undefined)
    out.bottom = cssLength(a.bottom)
  if (a.left !== undefined)
    out.left = cssLength(a.left)
  // Anchor to a panel via CSS Anchor Positioning.
  //
  // Passed as custom properties rather than as `position-anchor` /
  // `position-area` directly, because the fallback offsets above are
  // inline and inline styles beat any stylesheet rule — a supporting
  // browser could never override them. The scoped `@supports` block
  // consumes these and clears `inset`, so support decides which
  // positioning wins instead of specificity doing it.
  if (a.panel) {
    out['--wippy-anchor-name'] = panelAnchorName(a.panel)
    out['--wippy-anchor-area'] = a.area ?? 'right center'
  }
  return Object.keys(out).length > 0 ? out : null
})

/** True when this panel asked to be anchored to another panel. */
const panelAnchored = computed(() => !!props.def.anchor?.panel && !chrome.value)

const style = computed<Record<string, string>>(() => {
  const base: Record<string, string> = {
    zIndex: String((props.def.zIndex ?? 1000) + props.stackIndex),
  }
  const anchored = anchorStyle.value
  if (!anchored) {
    base.width = `${w.value}px`
    base.height = `${h.value}px`
    base.left = `${x.value}px`
    base.top = `${y.value}px`
    return base
  }

  // An axis pinned on BOTH sides is a stretch instruction, and CSS
  // over-constrained resolution ignores the second inset while the
  // dimension is non-auto — so a full-height edge rail
  // (`{ right: 0, top: 0, bottom: 0 }`) silently stayed at its declared
  // `size.height` at every viewport. Leave the dimension off and let the
  // insets size it, as they would in plain CSS.
  const stretchX = anchored.left !== undefined && anchored.right !== undefined
  const stretchY = anchored.top !== undefined && anchored.bottom !== undefined
  if (!stretchX)
    base.width = `${w.value}px`
  if (!stretchY)
    base.height = `${h.value}px`

  const offsets: Record<string, string> = { ...anchored }
  // Only fall back to the pixel position on axes the anchor leaves open,
  // so `{ right: 0 }` still pins vertically via `position.y`.
  if (anchored.left === undefined && anchored.right === undefined)
    offsets.left = `${x.value}px`
  if (anchored.top === undefined && anchored.bottom === undefined)
    offsets.top = `${y.value}px`
  // A single centring offset would put the panel's top-left at the
  // midpoint rather than its centre; pull it back by half its own size.
  let transform = ''
  if (anchored.top === '50%' && anchored.bottom === undefined)
    transform = 'translateY(-50%)'
  if (anchored.left === '50%' && anchored.right === undefined)
    transform = `${transform ? `${transform} ` : ''}translateX(-50%)`

  if (!panelAnchored.value) {
    // No `@supports` rule targets this element, so nothing can conflict
    // with inline offsets.
    if (transform)
      base.transform = transform
    return { ...base, ...offsets }
  }

  // Panel-anchored: hand the fallback offsets over as custom properties
  // rather than as inline `top`/`left`/`transform`.
  //
  // A style attribute outranks every non-`!important` stylesheet rule, so
  // an inline `top: 0` would survive the `@supports` block's `inset: auto`
  // and be resolved against the ANCHOR-derived containing block — an edge
  // tab asking for `top: 0` would jump to the top of the viewport on a
  // supporting engine and be correct only on one without it. Routing them
  // through variables consumed by a base rule puts both candidates in the
  // stylesheet, where `@supports` wins by source order instead of losing
  // to specificity.
  base['--wippy-anchor-name'] = anchored['--wippy-anchor-name']
  base['--wippy-anchor-area'] = anchored['--wippy-anchor-area']
  for (const side of ['top', 'right', 'bottom', 'left'] as const) {
    if (offsets[side] !== undefined)
      base[`--wippy-anchor-${side}`] = offsets[side]
  }
  if (transform)
    base['--wippy-anchor-transform'] = transform
  return base
})

const title = computed(() => props.def.title ?? props.id)
const dismissable = computed(() => props.def.dismissable !== false)

// Sync local refs when the def prop changes from outside (another
// iframe, programmatic host mutation, breakpoint flip). We watch
// `props.def` directly instead of chasing the manager's `change`
// event — `change` fires before LayoutManagerView re-renders with
// fresh props, so reading `props.def.*` inside the change callback
// sees stale values. Vue's prop-driven reactivity is the right
// source of truth here.
//
// Ignored while dragging so user input isn't fought by remote writes.
watch(
  () => [props.def.position.x, props.def.position.y, props.def.size.width, props.def.size.height] as const,
  ([nx, ny, nw, nh]) => {
    if (dragging.value)
      return
    x.value = nx
    y.value = ny
    w.value = nw
    h.value = nh
  },
)
</script>

<template>
  <!--
    `data-wippy-floating` makes a floating panel addressable by id, the
    same way `data-wippy-panel` does for slots. Without it the only hook
    was the shared `.wippy-layout-floating` class, so anything reaching
    for a specific float silently got whichever one happened to be first.
  -->
  <div
    ref="root"
    class="wippy-layout-floating"
    :data-wippy-floating="id"
    :class="[dragging && 'wippy-layout-floating--dragging', !chrome && 'wippy-layout-floating--bare', panelAnchored && 'wippy-layout-floating--panel-anchored']"
    :style="style"
    :role="chrome ? 'dialog' : undefined"
    :aria-label="chrome ? title : undefined"
    tabindex="-1"
    @mousedown="onFocusToTop"
  >
    <div
      v-if="chrome"
      class="wippy-layout-floating__header"
      @pointerdown="e => beginDrag(e, 'move')"
    >
      <span class="wippy-layout-floating__title">{{ title }}</span>
      <button
        v-if="dismissable"
        class="wippy-layout-floating__close"
        type="button"
        aria-label="Close"
        @click.stop="onClose"
      >
        ×
      </button>
    </div>
    <div class="wippy-layout-floating__content">
      <!--
        Wrap in PanelSlotContext so resolvers (PageResolver, ComponentResolver,
        etc.) inside the floating window can call useLayoutSlot() and receive
        a synthetic slot keyed on the floating panel's id. Without this the
        content's setup() throws "useLayoutSlot() called outside a
        LayoutPanelSlot" and the panel never mounts.
      -->
      <PanelSlotContext :panel-id="id" :tree="{ direction: 'vertical', children: [] }" :manager="manager">
        <component :is="def.component" v-bind="def.props ?? {}" />
      </PanelSlotContext>
    </div>

    <!-- Resize grips: 4 edges + 4 corners (windowed mode only) -->
    <template v-if="chrome">
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--n" @pointerdown="e => beginDrag(e, 'n')" />
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--s" @pointerdown="e => beginDrag(e, 's')" />
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--e" @pointerdown="e => beginDrag(e, 'e')" />
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--w" @pointerdown="e => beginDrag(e, 'w')" />
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--ne" @pointerdown="e => beginDrag(e, 'ne')" />
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--nw" @pointerdown="e => beginDrag(e, 'nw')" />
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--se" @pointerdown="e => beginDrag(e, 'se')" />
      <div class="wippy-layout-floating__grip wippy-layout-floating__grip--sw" @pointerdown="e => beginDrag(e, 'sw')" />
    </template>
  </div>
</template>

<style scoped>
.wippy-layout-floating {
  position: fixed;
  display: flex;
  flex-direction: column;
  background: var(--wippy-layout-floating-bg, #fff);
  color: var(--wippy-layout-floating-fg, inherit);
  border: 1px solid var(--wippy-layout-border-color, rgba(0, 0, 0, 0.1));
  border-radius: 6px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15), 0 2px 6px rgba(0, 0, 0, 0.08);
  overflow: visible;
  user-select: none;
  touch-action: none;
}
/*
 * Viewport-edge fallback for a panel-anchored flap.
 *
 * These live in the stylesheet, fed by custom properties, precisely so
 * the `@supports` block below can beat them by source order. Inline
 * offsets would outrank it — a style attribute wins over every
 * non-`!important` rule — and the two positioning systems would both
 * apply, resolving the insets against the anchor's containing block.
 */
.wippy-layout-floating--panel-anchored {
  top: var(--wippy-anchor-top, auto);
  right: var(--wippy-anchor-right, auto);
  bottom: var(--wippy-anchor-bottom, auto);
  left: var(--wippy-anchor-left, auto);
  transform: var(--wippy-anchor-transform, none);
}
/*
 * CSS Anchor Positioning, applied only where the browser has it.
 *
 * `inset: auto` drops the fallback above so the anchor decides placement
 * outright; without it the two would fight. A browser without the feature
 * never sees this block and keeps the fallback.
 */
@supports (position-area: center) {
  .wippy-layout-floating--panel-anchored {
    position-anchor: var(--wippy-anchor-name);
    position-area: var(--wippy-anchor-area, right center);
    inset: auto;
    /* The fallback needed a manual half-size pull-back to centre; the
       anchor engine centres for us, so undo it. */
    transform: none;
  }
}

.wippy-layout-floating--dragging {
  opacity: 0.95;
}
/*
 * Bare flap (`chrome: false`): strip the window frame so only the
 * panel content shows at the pinned position/size. Content overflow is
 * `visible` (base is `auto`) so an edge tab's hover menu can expand
 * beyond the box. Root keeps `position: fixed` + `overflow: visible`.
 */
.wippy-layout-floating--bare {
  background: transparent;
  border: none;
  border-radius: 0;
  box-shadow: none;
}
.wippy-layout-floating--bare .wippy-layout-floating__content {
  overflow: visible;
  user-select: auto;
}
.wippy-layout-floating__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: var(--wippy-layout-floating-header-bg, #f7f7f8);
  border-bottom: 1px solid var(--wippy-layout-border-color, rgba(0, 0, 0, 0.08));
  cursor: grab;
  touch-action: none;
  font: 600 0.875rem/1.2 system-ui, sans-serif;
}
.wippy-layout-floating__header:active {
  cursor: grabbing;
}
.wippy-layout-floating__title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wippy-layout-floating__close {
  background: none;
  border: none;
  font-size: 1.25rem;
  line-height: 1;
  padding: 0 0.25rem;
  cursor: pointer;
  color: inherit;
  opacity: 0.6;
}
.wippy-layout-floating__close:hover {
  opacity: 1;
}
.wippy-layout-floating__content {
  flex: 1 1 auto;
  overflow: auto;
  user-select: text;
}

/*
 * Grip zones — invisible hitboxes on every edge + corner. ::before
 * would conflict with the existing div tree, so use explicit grip
 * elements positioned absolutely around the window.
 */
.wippy-layout-floating__grip {
  position: absolute;
  z-index: 1;
  --grip: 6px;
}
@media (pointer: coarse) {
  .wippy-layout-floating__grip {
    --grip: 16px;
  }
}
.wippy-layout-floating__grip--n { top: calc(-1 * var(--grip) / 2); left: var(--grip); right: var(--grip); height: var(--grip); cursor: ns-resize; }
.wippy-layout-floating__grip--s { bottom: calc(-1 * var(--grip) / 2); left: var(--grip); right: var(--grip); height: var(--grip); cursor: ns-resize; }
.wippy-layout-floating__grip--e { top: var(--grip); bottom: var(--grip); right: calc(-1 * var(--grip) / 2); width: var(--grip); cursor: ew-resize; }
.wippy-layout-floating__grip--w { top: var(--grip); bottom: var(--grip); left: calc(-1 * var(--grip) / 2); width: var(--grip); cursor: ew-resize; }
.wippy-layout-floating__grip--ne { top: calc(-1 * var(--grip) / 2); right: calc(-1 * var(--grip) / 2); width: calc(var(--grip) * 2); height: calc(var(--grip) * 2); cursor: nesw-resize; }
.wippy-layout-floating__grip--nw { top: calc(-1 * var(--grip) / 2); left: calc(-1 * var(--grip) / 2); width: calc(var(--grip) * 2); height: calc(var(--grip) * 2); cursor: nwse-resize; }
.wippy-layout-floating__grip--se { bottom: calc(-1 * var(--grip) / 2); right: calc(-1 * var(--grip) / 2); width: calc(var(--grip) * 2); height: calc(var(--grip) * 2); cursor: nwse-resize; }
.wippy-layout-floating__grip--sw { bottom: calc(-1 * var(--grip) / 2); left: calc(-1 * var(--grip) / 2); width: calc(var(--grip) * 2); height: calc(var(--grip) * 2); cursor: nesw-resize; }
</style>
