<script setup lang="ts">
import type { AttentionLayoutHandle, AttentionLayoutPanel, AttentionLayoutRegistration } from '@wippy-fe/shared'
/**
 * Top-level manager view. Renders three things:
 *
 *   1. The active layout TREE — flex containers with anchor slots
 *      (`LayoutPanelSlot`). Anchors take flex space and register their
 *      DOM element with the `LAYOUT_ANCHOR_REGISTRY_KEY` registry.
 *   2. The MOUNT zone — one stable wrapper per panel id, positioned
 *      absolutely to overlay its anchor's rect. ResizeObserver tracks
 *      the anchor's geometry and updates the wrapper's left/top/
 *      width/height. The wrapper itself never moves between DOM
 *      parents, so iframes / web components inside keep their
 *      document and state across breakpoint flips that swap the
 *      anchor element.
 *   3. Floating + modal overlays — orthogonal `<Teleport>` to body.
 *
 * Why an overlay-tracker instead of `<Teleport>`: Vue's Teleport moves
 * DOM nodes between parents when the target changes. Browsers RELOAD
 * iframes whenever their element is removed-and-reinserted (even via
 * `appendChild`), so a teleport-based design loses iframe document
 * state on every breakpoint flip. Keeping the wrapper anchored to a
 * fixed parent and CSS-positioning it over the anchor sidesteps this.
 */
import type { LayoutManager } from './layout-manager'
import type { LayoutDeclaration, PanelSlot, PanelTree } from './types'
import { computed, onBeforeUnmount, onMounted, provide, reactive, ref, shallowRef, watch } from 'vue'
import { LAYOUT_ANCHOR_REGISTRY_KEY } from './composables'
import { deriveMobileLayout, isDrawerSlot, pickBreakpoint, walkTree } from './helpers'
import LayoutDrawerAnchor from './LayoutDrawerAnchor.vue'
import LayoutFloating from './LayoutFloating.vue'
import LayoutModal from './LayoutModal.vue'
import LayoutModalNative from './LayoutModalNative.vue'
import LayoutTree from './LayoutTree.vue'
import PanelSlotContext from './PanelSlotContext.vue'

const props = defineProps<{
  manager: LayoutManager
}>()

/**
 * Modal component dispatcher. Defaults to the native `<dialog showModal()>`
 * implementation (top-layer stacking, focus trap, inert propagation,
 * native ::backdrop). Consumers can opt back into the legacy div-overlay
 * implementation per-modal via `def.useNativeDialog: false` while they
 * migrate. The legacy `LayoutModal` is `@deprecated` and will be removed
 * in the next major.
 *
 * The choice is per-modal, not global, so a stack of modals can mix-and-
 * match during a transitional release.
 */
// Feature-detect once at module load — `HTMLDialogElement` doesn't
// appear or disappear over a page lifetime, so re-evaluating per render
// is wasted work. SSR-safe: when `window` is undefined we assume native
// support so the snapshot renders the modern path; the actual platform
// check re-runs at hydration where `window` exists.
const NATIVE_DIALOG_SUPPORTED
  = typeof window === 'undefined' || typeof window.HTMLDialogElement !== 'undefined'

// Falls back to legacy `LayoutModal` either when the caller explicitly
// opts out (`useNativeDialog: false`) or when the runtime lacks
// `<dialog>` support (very old browsers / JSDOM).
function pickModalComponent(useNativeDialog: boolean | undefined) {
  return useNativeDialog === false || !NATIVE_DIALOG_SUPPORTED ? LayoutModal : LayoutModalNative
}

const root = ref<HTMLDivElement | null>(null)

/**
 * Reactive snapshot of the current declaration. Updated via `change` subscription.
 */
const decl = shallowRef<LayoutDeclaration>(props.manager.getLayout())
const activeBreakpoint = ref<string>('default')

const activeTree = computed<PanelTree>(() => {
  const tree = decl.value.layouts[activeBreakpoint.value]
  if (tree)
    return tree
  if (activeBreakpoint.value !== 'default') {
    return deriveMobileLayout(decl.value)
  }
  return decl.value.layouts.default
})

/**
 * Set of panel ids currently visible in the active tree. Used to gate
 * which mount wrappers are sized > 0 (hidden ones get `display: none`
 * via the missing-anchor rect-zero path).
 *
 * Drawer-mode slots ARE included here — they're "visible" to the panel
 * registry even when the drawer is closed, so the panel host stays
 * alive (form state, scroll, iframe DOM all preserved across drawer
 * open/close AND across breakpoint flips that switch a panel between
 * inline and drawer display).
 */
const activePanelIds = computed<Set<string>>(() => {
  const ids = new Set<string>()
  walkTree(activeTree.value, (slot: PanelSlot) => {
    ids.add(slot.panel)
  })
  return ids
})

const activeSlotChrome = computed<Record<string, { borderBefore: boolean, direction: PanelTree['direction'] }>>(() => {
  const result: Record<string, { borderBefore: boolean, direction: PanelTree['direction'] }> = {}
  function visit(tree: PanelTree) {
    for (const child of tree.children) {
      if ('panel' in child) {
        result[child.panel] = {
          borderBefore: child.borderBefore === true,
          direction: tree.direction,
        }
      }
      else {
        visit(child)
      }
    }
  }
  visit(activeTree.value)
  return result
})

/**
 * Stable, canonical order of ALL declared panel ids — used to drive
 * the mount-zone v-for. Iterating over this (instead of the active
 * tree's panel set) keeps every mount wrapper at the SAME DOM
 * position across breakpoint flips. That matters because Vue's keyed
 * v-for reorders elements via `insertBefore`, which is a DOM
 * remove-and-insert at the platform level — and browsers reload
 * iframes whenever their element is removed and reinserted, even when
 * it lands back in the same parent. Keeping the v-for input stable
 * means nothing reorders, nothing reloads.
 *
 * Wrappers for panels NOT in the active tree are CSS-hidden via the
 * zero-rect path (their anchor entry is null → `panelRects[id]` is
 * `{0,0,0,0,visible:false}` → `display: none` via the visibility
 * style binding).
 */
const allPanelIds = computed<string[]>(() => Object.keys(decl.value.panels))

/**
 * Drawer-mode slots in the active tree. One overlay anchor rendered
 * per entry, positioned at the named edge. The flat panel zone
 * teleports panel content to whichever anchor (inline `LayoutPanelSlot`
 * or this drawer anchor) is currently registered for the panel id.
 */
const activeDrawerSlots = computed<PanelSlot[]>(() => {
  const slots: PanelSlot[] = []
  walkTree(activeTree.value, (slot: PanelSlot) => {
    if (isDrawerSlot(slot))
      slots.push(slot)
  })
  return slots
})

/**
 * True when at least one drawer in the active tree has its `drawerOpen`
 * panel-state flag set. Drives the backdrop visibility — clicking the
 * backdrop closes every open drawer in one go.
 */
const anyDrawerOpen = computed<boolean>(() => {
  for (const slot of activeDrawerSlots.value) {
    if (decl.value.panels[slot.panel]?.drawerOpen)
      return true
  }
  return false
})

const openDrawerPanelIds = computed<Set<string>>(() => {
  const ids = new Set<string>()
  for (const slot of activeDrawerSlots.value) {
    if (decl.value.panels[slot.panel]?.drawerOpen)
      ids.add(slot.panel)
  }
  return ids
})

/**
 * A closed drawer stays mounted to preserve its content, but it must not be
 * reported as logically visible to a retained child page or web component.
 */
const presentedPanelIds = computed<Set<string>>(() => {
  const ids = new Set<string>()
  walkTree(activeTree.value, (slot: PanelSlot) => {
    if (!isDrawerSlot(slot) || openDrawerPanelIds.value.has(slot.panel))
      ids.add(slot.panel)
  })
  return ids
})

/**
 * A closed drawer's anchor rests at its edge, inside the layout, at full size
 * (see `LayoutDrawerAnchor`), so its mount keeps one rect: the content does not
 * reflow, and nothing extends an ancestor's scrollable area. Like a panel
 * collapsed to nothing, it is hidden and non-interactive.
 */
function closedDrawer(panelId: string): boolean {
  return activePanelIds.value.has(panelId) && !presentedPanelIds.value.has(panelId)
}

function closeAllDrawers() {
  for (const slot of activeDrawerSlots.value) {
    if (decl.value.panels[slot.panel]?.drawerOpen)
      props.manager.closeDrawer(slot.panel)
  }
}

/**
 * Panel-id → anchor DOM element. Slot anchors write into this on
 * mount; the mount-zone reads it to size + position each panel
 * wrapper. `reactive` makes downstream watchers re-fire when an
 * anchor element swaps (e.g., breakpoint flip recreates a slot, or
 * inline ↔ drawer transition rewrites the anchor).
 */
const anchorRegistry = reactive<Record<string, HTMLElement | null>>({})
provide(LAYOUT_ANCHOR_REGISTRY_KEY, anchorRegistry)

/**
 * Per-panel position/size derived from the current anchor's
 * `getBoundingClientRect()`, expressed RELATIVE to the manager-view
 * root. Each entry is the absolute style applied to the panel's
 * mount-zone wrapper — keeping the wrapper itself anchored to a
 * stable parent while it visually tracks whichever anchor is
 * currently active for that panel id.
 */
interface PanelRect { left: number, top: number, width: number, height: number, visible: boolean, measured: boolean }
const panelRects = reactive<Record<string, PanelRect>>({})

/**
 * A panel collapsed to nothing is closed, not merely thin.
 *
 * A slot with `collapseSize: '0px'` still resolves to an *active* panel, so
 * without this its mount kept `visibility: visible` at zero size. A zero-sized
 * mount paints nothing, but `overflow: visible` (deliberate — §5.1, popovers
 * must escape panel bounds) means its content still lays out at natural size
 * beside it. That content stayed focusable: tabbing out of the neighbouring
 * panel walked into a panel the user had closed, and the browser scrolled an
 * ancestor to bring the focused control into view — so Tab dragged a closed
 * panel back onto screen. The same overflow inflates the scrollable width of
 * any `overflow: hidden` ancestor, which is what makes the shift visible.
 *
 * The fix is not to clip: that would break §5.1. It is to treat "collapsed to
 * zero" the way an inactive mount is already treated one branch below —
 * hidden and non-interactive. Nothing is lost visually, because a zero-sized
 * mount had nothing to show.
 *
 * The threshold is exactly zero, which makes the `collapseSize` contract
 * legible: `0` closes a panel; any non-zero value keeps it on screen and
 * interactive. A collapsed rail that must stay clickable therefore has to be
 * given a real size — which it needs anyway to draw its expand affordance.
 */
function collapsedToNothing(panelId: string): boolean {
  if (!activePanelIds.value.has(panelId))
    return false
  const rect = panelRects[panelId]
  // `measured` guards the first frame: an unmeasured rect is also all-zero,
  // and treating that as collapsed would hide every panel until its anchor
  // registers.
  return !!rect && rect.measured && !rect.visible
}

/** In the layout, with nothing to show. */
function panelHidden(panelId: string): boolean {
  return collapsedToNothing(panelId) || closedDrawer(panelId)
}

const anchorObserver = ref<ResizeObserver | null>(null)
/** Reverse map: anchor element → panelId, so the observer callback can find which panel changed. */
const elementToPanelId = new WeakMap<Element, string>()

function readPanelRect(panelId: string): PanelRect {
  const anchor = anchorRegistry[panelId]
  const rootEl = root.value
  if (!anchor || !rootEl) {
    // Not measurable yet. Distinct from "measured and zero-sized": callers
    // must not treat an unmeasured panel as collapsed, or panels would be
    // hidden on the frame before their anchor registers.
    return { left: 0, top: 0, width: 0, height: 0, visible: false, measured: false }
  }
  const ar = anchor.getBoundingClientRect()
  const rr = rootEl.getBoundingClientRect()
  return {
    left: ar.left - rr.left,
    top: ar.top - rr.top,
    width: ar.width,
    height: ar.height,
    // Zero-sized means collapsed; see `collapsedToNothing`. A closed drawer's
    // anchor keeps its real size, so it is hidden by `closedDrawer` instead.
    visible: ar.width > 0 && ar.height > 0,
    measured: true,
  }
}

function refreshPanelRect(panelId: string) {
  panelRects[panelId] = readPanelRect(panelId)
}

function refreshAllPanelRects() {
  for (const panelId of Object.keys(anchorRegistry)) {
    refreshPanelRect(panelId)
  }
}

/**
 * Track changes in the anchor registry: each newly-set anchor element
 * gets observed (so size changes refresh its rect), each cleared
 * anchor's element is unobserved. The element→panelId map lets the
 * observer callback look up which panel id needs refreshing without
 * scanning the whole registry on every fire.
 */
watch(
  () => Object.entries(anchorRegistry).map(([id, el]) => `${id}:${el ? '1' : '0'}`).join(','),
  () => {
    const obs = anchorObserver.value
    if (!obs)
      return
    for (const [panelId, el] of Object.entries(anchorRegistry)) {
      if (el) {
        const existing = elementToPanelId.get(el)
        if (existing !== panelId) {
          elementToPanelId.set(el, panelId)
          obs.observe(el)
        }
        refreshPanelRect(panelId)
      }
      else {
        // Anchor cleared. The element was already disconnected from DOM
        // by Vue when the previous anchor unmounted, so the observer
        // entry is harmless — but we mark the panel rect as zero so the
        // wrapper collapses until a new anchor registers.
        // `measured: false` matters here: this zero is "between anchors", not
        // "collapsed to nothing". Marking it measured would hide the panel for
        // the duration of a breakpoint flip.
        panelRects[panelId] = { left: 0, top: 0, width: 0, height: 0, visible: false, measured: false }
      }
    }
  },
  { flush: 'post' },
)

const floatingEntries = computed(() => Object.entries(decl.value.floating ?? {}))
const modalEntries = computed(() => Object.entries(decl.value.modals ?? {}))

let unsubChange: (() => void) | null = null
let unsubBreakpoint: (() => void) | null = null
let resizeObs: ResizeObserver | null = null
let rafHandle = 0
let pendingWidth = 0
let warnedMissingNarrow = false

function pickAndApplyBreakpoint(width: number) {
  const name = pickBreakpoint(width, decl.value)
  if (name !== activeBreakpoint.value) {
    activeBreakpoint.value = name
    props.manager.setActiveBreakpoint(name, width)
  }
  maybeWarnMissingNarrow(width)
}

function schedulePick(width: number) {
  pendingWidth = width
  if (rafHandle)
    return
  rafHandle = requestAnimationFrame(() => {
    rafHandle = 0
    pickAndApplyBreakpoint(pendingWidth)
  })
}

function maybeWarnMissingNarrow(width: number) {
  if (warnedMissingNarrow)
    return
  const { layouts, breakpoints } = decl.value
  const narrowThreshold = breakpoints?.sm ?? 640
  if (width < narrowThreshold && !layouts.sm) {
    warnedMissingNarrow = true
    console.warn(
      `[@wippy-fe/layout] Container width (${Math.round(width)}px) is below the `
      + `"sm" breakpoint threshold (${narrowThreshold}px) but no layouts.sm is `
      + `declared. Falling back to deriveMobileLayout (single-slot). Declare a `
      + `layouts.sm entry to take control of the narrow-viewport rendering.`,
    )
  }
}

function onWindowResize() {
  refreshAllPanelRects()
}

const attentionElements = reactive<Record<string, HTMLElement | null>>({})
let attentionHandle: AttentionLayoutHandle | undefined

function setAttentionElement(key: string, value: unknown) {
  attentionElements[key] = value && (value as Element).nodeType === 1 ? value as HTMLElement : null
}

/**
 * Hiding a control blurs it, but an iframe keeps the keyboard when it is
 * hidden, so typing would go on reaching the closed drawer's page.
 */
function releaseFocus(panelId: string) {
  const mount = attentionElements[`panel:${panelId}`]
  const active = (mount?.getRootNode() as Document | ShadowRoot | undefined)?.activeElement
  if (active instanceof HTMLElement && mount?.contains(active))
    active.blur()
}

watch(openDrawerPanelIds, (_open, wasOpen) => {
  for (const panelId of wasOpen) {
    if (closedDrawer(panelId))
      releaseFocus(panelId)
  }
})

function syncAttentionLayout() {
  if (!root.value)
    return
  const slots = new Map<string, PanelSlot>()
  walkTree(activeTree.value, slot => slots.set(slot.panel, slot))
  const panels: AttentionLayoutPanel[] = Object.entries(decl.value.panels).map(([id, definition]) => ({
    id,
    element: attentionElements[`panel:${id}`],
    title: definition.title || undefined,
    active: presentedPanelIds.value.has(id),
    collapsed: slots.get(id)?.collapsed === true,
    drawer: Boolean(slots.get(id) && isDrawerSlot(slots.get(id)!)),
    floating: false,
    modal: false,
    placeholder: !attentionElements[`panel:${id}`],
  }))
  for (const kind of ['floating', 'modals'] as const) {
    for (const [id, definition] of Object.entries(decl.value[kind] ?? {})) {
      const element = attentionElements[`${kind}:${id}`]
      panels.push({ id, element, title: definition.title || undefined, active: true, collapsed: false, drawer: false, floating: kind === 'floating', modal: kind === 'modals', placeholder: !element })
    }
  }
  for (const modal of props.manager.getRegisteredModals()) {
    if (!decl.value.modals?.[modal.id])
      panels.push({ id: modal.id, title: modal.title, active: false, collapsed: false, drawer: false, floating: false, modal: true, placeholder: true })
  }
  const state = { panels, breakpoint: activeBreakpoint.value }
  if (attentionHandle) {
    attentionHandle.update(state)
    return
  }
  const view = root.value.ownerDocument.defaultView as (Window & { __WIPPY_APP_API__?: { attention?: { enabled?: boolean, registerLayoutProvider?: (input: AttentionLayoutRegistration) => AttentionLayoutHandle } } }) | null
  const attention = view?.__WIPPY_APP_API__?.attention
  if (attention?.enabled && attention.registerLayoutProvider)
    attentionHandle = attention.registerLayoutProvider({ ...state, root: root.value })
}

watch([decl, activeBreakpoint, activeTree, () => Object.entries(attentionElements)], syncAttentionLayout, { flush: 'post' })

onMounted(() => {
  syncAttentionLayout()
  // Anchor-rect observer. ResizeObserver fires on size changes for any
  // observed anchor element — covers splitter drag, drawer width
  // updates, and content reflows that change a slot's geometry.
  // Position-only changes (e.g., adjacent slot grew, sliding this one
  // sideways) aren't covered by ResizeObserver alone; the manager's
  // `change` subscription below + window-resize listener catch those.
  if (typeof ResizeObserver !== 'undefined') {
    anchorObserver.value = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const panelId = elementToPanelId.get(entry.target)
        if (panelId)
          refreshPanelRect(panelId)
      }
    })
  }
  window.addEventListener('resize', onWindowResize)

  unsubChange = props.manager.on('change', (next) => {
    decl.value = next
    // Layout tree changes can cause anchor rect shifts even when no
    // anchor element itself changed size (e.g., a drawer toggling open
    // pushes adjacent inline slots). Refresh after Vue settles the DOM.
    queueMicrotask(refreshAllPanelRects)
  })
  // Mirror manager.activeBreakpoint into our local ref so programmatic
  // `manager.setActiveBreakpoint(...)` calls (tests, custom router
  // bindings, etc.) drive the view too. ResizeObserver-originated
  // updates set both manager + ref synchronously above and the
  // resulting `breakpoint` emit is then a no-op (guarded by the
  // value comparison in `pickAndApplyBreakpoint`).
  unsubBreakpoint = props.manager.on('breakpoint', ({ name }) => {
    if (activeBreakpoint.value !== name)
      activeBreakpoint.value = name
  })
  // Pick up the manager's current breakpoint at mount so initial
  // render reflects any pre-set state.
  if (props.manager.activeBreakpoint !== activeBreakpoint.value)
    activeBreakpoint.value = props.manager.activeBreakpoint

  if (root.value && typeof ResizeObserver !== 'undefined') {
    resizeObs = new ResizeObserver((entries) => {
      const entry = entries[0]
      if (!entry)
        return
      schedulePick(entry.contentRect.width)
    })
    resizeObs.observe(root.value)
    pickAndApplyBreakpoint(root.value.getBoundingClientRect().width)
  }
})

onBeforeUnmount(() => {
  attentionHandle?.dispose()
  attentionHandle = undefined
  unsubChange?.()
  unsubBreakpoint?.()
  resizeObs?.disconnect()
  anchorObserver.value?.disconnect()
  window.removeEventListener('resize', onWindowResize)
  if (rafHandle)
    cancelAnimationFrame(rafHandle)
})
</script>

<template>
  <div
    ref="root"
    class="wippy-layout-manager-view"
    :data-breakpoint="activeBreakpoint"
  >
    <LayoutTree :tree="activeTree" :manager="manager" />

    <!--
      Stable mount zone. Each panel id renders ONCE here, in a wrapper
      that's absolutely positioned to overlay its current anchor's
      bounding rect. The wrapper itself never moves between DOM parents
      across breakpoint flips or inline ↔ drawer transitions, so any
      iframes or stateful web components inside keep their document
      and state — only the wrapper's `left/top/width/height` styles
      update via `panelRects`, driven by ResizeObserver +
      manager.change + window-resize listeners.

      `pointer-events: none` on the host layer + `auto` on each wrapper
      lets clicks pass through gaps to the layout tree below (e.g.
      splitter-handle areas between mounted panels).
    -->
    <div class="wippy-layout-panel-host" aria-hidden="false">
      <template v-for="panelId in allPanelIds" :key="panelId">
        <!--
          Addressed as `[data-wippy-panel-mount="<id>"]`, never
          `[data-wippy-panel]`. The two are deliberately distinct:
          `data-wippy-panel` marks the panel's *layout position* and
          exists only while the panel is in the active tree, whereas this
          mount host persists for every declared panel so its content
          survives breakpoint flips. Carrying both here made
          `[data-wippy-panel="<id>"]` resolve to two nested elements and
          left the public selector ambiguous.
        -->
        <div
          :ref="el => setAttentionElement(`panel:${panelId}`, el)"
          class="wippy-layout-panel-mount"
          :class="[
            activeSlotChrome[panelId]?.borderBefore && 'wippy-layout-panel-mount--border-before',
            activeSlotChrome[panelId] && `wippy-layout-panel-mount--${activeSlotChrome[panelId].direction}`,
            openDrawerPanelIds.has(panelId) && 'wippy-layout-panel-mount--drawer-open',
          ]"
          :data-wippy-panel-mount="panelId"
          :data-wippy-panel-active="activePanelIds.has(panelId) ? 'true' : 'false'"
          :data-wippy-panel-collapsed="collapsedToNothing(panelId) ? 'true' : undefined"
          :inert="panelHidden(panelId) ? true : undefined"
          :style="activePanelIds.has(panelId)
            ? {
              display: 'flex',
              left: `${(panelRects[panelId]?.left ?? 0)}px`,
              top: `${(panelRects[panelId]?.top ?? 0)}px`,
              width: `${(panelRects[panelId]?.width ?? 0)}px`,
              height: `${(panelRects[panelId]?.height ?? 0)}px`,
              // Nothing to paint, so hide it rather than leave its content
              // focusable. Same treatment as the inactive branch below; see
              // `collapsedToNothing`. A descendant can set its own `visibility`
              // and `pointer-events`, and this mount sits over other panels,
              // so `clip-path` and `inert` cover the whole subtree. Hidden
              // content still counts as scrollable overflow, so the mount also
              // bounds it instead of keeping `overflow: visible`.
              visibility: panelHidden(panelId) ? 'hidden' : undefined,
              pointerEvents: panelHidden(panelId) ? 'none' : undefined,
              clipPath: panelHidden(panelId) ? 'inset(100%)' : undefined,
              overflow: panelHidden(panelId) ? 'clip' : undefined,
              // Only the open drawer is promoted (over its anchor at 900).
              // Inline mounts stay `auto`: `position: absolute` + a numeric
              // z-index makes a stacking context, trapping the panel's own
              // popovers inside its rect.
              zIndex: openDrawerPanelIds.has(panelId) ? '901' : undefined,
            }
            : {
              display: 'flex',
              visibility: 'hidden',
              pointerEvents: 'none',
              left: '-9999px',
              top: '0',
              width: '0',
              height: '0',
            }"
        >
          <PanelSlotContext
            :panel-id="panelId"
            :tree="activeTree"
            :manager="manager"
            :presented="presentedPanelIds.has(panelId)"
          >
            <component
              :is="decl.panels[panelId].component"
              v-bind="decl.panels[panelId].props ?? {}"
              class="wippy-layout-slot__content"
            />
          </PanelSlotContext>
        </div>
      </template>
    </div>

    <!--
      Drawer overlay zone. One absolutely-positioned anchor per drawer
      slot in the active tree, regardless of open/closed state.
      Anchors stay mounted across open/close transitions so the
      teleported panel content (and its iframe / WC / form state)
      survives.
    -->
    <LayoutDrawerAnchor
      v-for="slot in activeDrawerSlots"
      :key="`drawer:${slot.panel}`"
      :slot-def="slot"
      :manager="manager"
    />

    <!--
      Shared backdrop — visible when any drawer in the active layout is
      open. Click closes every open drawer in one go (matches the
      common UX expectation; consumers wanting per-drawer modal-style
      behavior can prevent the click via a custom backdrop or call
      `openDrawer` again right after).
    -->
    <div
      v-if="anyDrawerOpen"
      class="wippy-layout-drawer-backdrop"
      role="presentation"
      @click="closeAllDrawers"
    />

    <Teleport to="body">
      <LayoutFloating
        v-for="([id, def], i) in floatingEntries"
        :id="id"
        :key="`floating:${id}`"
        :attention-element="el => setAttentionElement(`floating:${id}`, el)"
        :def="def"
        :manager="manager"
        :stack-index="i"
      />
    </Teleport>

    <Teleport to="body">
      <component
        :is="pickModalComponent(def.useNativeDialog)"
        v-for="([id, def], i) in modalEntries"
        :id="id"
        :key="`modal:${id}`"
        :attention-element="(el: HTMLElement | null) => setAttentionElement(`modals:${id}`, el)"
        :def="def"
        :manager="manager"
        :stack-index="i"
      />
    </Teleport>
  </div>
</template>

<style scoped>
.wippy-layout-manager-view {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: visible;
  position: relative;
