<script setup lang="ts">
import type { LayoutManager } from './layout-manager'
import type { PanelDivider, PanelSlot, PanelTree } from './types'
import { computed, reactive } from 'vue'
import { hasResizableSide, isDrawerSlot, isPanelSlot, parseSize } from './helpers'
import LayoutPanelSlot from './LayoutPanelSlot.vue'
import LayoutSplitter from './LayoutSplitter.vue'

defineOptions({ name: 'LayoutTree' })

const props = defineProps<{
  tree: PanelTree
  manager: LayoutManager
  /** True for a tree rendered inside another tree. Only nested trees take a `size`. */
  nested?: boolean
}>()

/**
 * Track size of a nested tree along its parent's axis. Same grammar as a
 * slot's `size`; `Npx` and `N%` fix the tree (no grow, no shrink), which is
 * what a dashboard row of a set height needs. A tree without `size`, and the
 * root, get no inline style and keep the `flex: 1 1 auto` of the class below.
 */
const sizeStyle = computed<Record<string, string> | undefined>(() => {
  const size = props.tree.size
  if (!props.nested || !size)
    return undefined
  const parsed = parseSize(size)
  if (!parsed)
    return undefined
  if (parsed.unit === 'auto')
    return { flex: '0 0 auto' }
  if (parsed.unit === 'fr')
    return { flex: `${parsed.value || 1} 1 0` }
  return { flex: `0 0 ${size}` }
})

const separatorDrag = computed(() => props.manager.capabilities.separatorDrag)

/**
 * Drawer-mode slots are lifted out of the grid by `LayoutManagerView` —
 * they render as overlay anchors elsewhere. Filter them out of the
 * children we paint here so they take no flex space and don't get a
 * splitter on either side.
 */
const visibleChildren = computed(() => {
  return props.tree.children.filter(c => !(isPanelSlot(c) && isDrawerSlot(c)))
})

/**
 * Element refs for every child — ordered by tree index. Splitters
 * read `childEls[i]` / `childEls[i + 1]` to measure their adjacent
 * siblings at drag-start, avoiding a DOM query by panel id. Works
 * uniformly for leaf slots AND nested trees.
 *
 * MUST be reactive: Vue evaluates the splitter's `:before-el` /
 * `:after-el` props during the parent's render, but child `:ref`
 * callbacks only fire after each child mounts (later in the same
 * patch). A plain array would lock the splitter's props at `null`
 * forever — drag would dead-end on first pointerdown. `reactive([])`
 * makes index writes trigger re-render of the dependent splitter.
 */
const childEls = reactive<Array<HTMLElement | null>>([])

function setChildEl(i: number, el: unknown) {
  // LayoutPanelSlot + LayoutTree both render a single root element; the
  // Vue ref we get back is the component instance — reach through to
  // `$el`. For literal `<div ref=...>` targets this would already be
  // the element, but both our children are components.
  const node = el && typeof el === 'object' && '$el' in el
    ? (el as { $el: HTMLElement }).$el
    : (el as HTMLElement | null)
  childEls[i] = node ?? null
}

function childAt(i: number): PanelSlot | PanelTree | null {
  return visibleChildren.value[i] ?? null
}

function dividerBefore(child: PanelSlot | PanelTree | null): PanelDivider {
  return child && isPanelSlot(child) ? child.dividerBefore ?? 'default' : 'default'
}

function childKey(child: PanelSlot | PanelTree, i: number): string {
  if (isPanelSlot(child))
    return `slot:${child.panel}`
  return `tree:${i}:${child.direction}:${child.children.length}`
}
</script>

<template>
  <div
    class="wippy-layout-tree"
    :class="[`wippy-layout-tree--${tree.direction}`]"
    :style="sizeStyle"
  >
    <template v-for="(child, i) in visibleChildren" :key="childKey(child, i)">
      <!-- Recursive: nested tree -->
      <LayoutTree
        v-if="!isPanelSlot(child)"
        :ref="(el) => setChildEl(i, el)"
        :tree="child"
        :manager="manager"
        nested
      />
      <!-- Leaf: panel slot (drawer-mode slots are filtered out of visibleChildren) -->
      <LayoutPanelSlot
        v-else
        :ref="(el) => setChildEl(i, el)"
        :slot-def="child"
        :direction="tree.direction"
        :manager="manager"
      />

      <!--
        Separator between this child and the next. Rendered only when
        at least one neighbor is a non-fixed, non-collapsed slot
        (AC §4.1 / §4.2 — chrome bands are non-resizable, so no
        splitter renders between two fixed chrome panels).
      -->
      <LayoutSplitter
        v-if="separatorDrag && i < visibleChildren.length - 1 && hasResizableSide(childAt(i), childAt(i + 1))"
        :direction="tree.direction"
        :before="childAt(i)"
        :after="childAt(i + 1)"
        :before-el="childEls[i] ?? null"
        :after-el="childEls[i + 1] ?? null"
        :paint="dividerBefore(childAt(i + 1))"
        :manager="manager"
      />
    </template>
  </div>
</template>

<style scoped>
.wippy-layout-tree {
  display: flex;
  overflow: visible;
  min-width: 0;
  min-height: 0;
  flex: 1 1 auto;
}
.wippy-layout-tree--horizontal {
  flex-direction: row;
}
.wippy-layout-tree--vertical {
  flex-direction: column;
}
</style>
