import type { Emitter } from 'nanoevents'
import type {
  FloatingPanelDef,
  LayoutCapabilities,
  LayoutDeclaration,
  LayoutEvents,
  ModalDef,
  PanelDef,
  PanelSlot,
  PanelTarget,
  PanelTree,
  SizeValue,
} from './types'
import { createNanoEvents } from 'nanoevents'
import {
  assertValidLayout,
  assertValidModalDef,
  cloneLayout,
  findSlotParent,
  insertAtPosition,
  moveNode,
  removeNode,
  walkTree,
} from './helpers'
import { DEFAULT_CAPABILITIES, LayoutValidationError } from './types'

/**
 * Declarative, imperatively-mutable multi-panel layout manager.
 *
 * Owns the LayoutDeclaration; every mutation emits `change`. Vue renderers
 * subscribe via composables; the class itself has no Vue dependency and is
 * unit-testable without a DOM.
 */
export class LayoutManager {
  private decl: LayoutDeclaration
  private readonly emitter: Emitter<LayoutEvents>
  private _activeBreakpoint = 'default'
  public readonly capabilities: Required<LayoutCapabilities>
  /**
   * Pre-registered modal templates. `openModal(id)` (no def) looks up
   * here; `openModal(id, def)` re-registers under the same id so
   * subsequent id-only opens reuse the latest shape.
   *
   * Initial declaration's `modals` block is hoisted into this registry
   * at construction — i.e. listing a modal in the declaration REGISTERS
   * it (closed) rather than opening it. Boot state always has zero
   * modals open; consumers call `openModal(id)` to actually display.
   */
  private modalRegistry: Map<string, ModalDef> = new Map()

  constructor(
    declaration: LayoutDeclaration,
    capabilities?: LayoutCapabilities,
  ) {
    this.capabilities = { ...DEFAULT_CAPABILITIES, ...(capabilities ?? {}) }

    if (this.capabilities.panelDrag) {
      throw new LayoutValidationError([{
        kind: 'capability-reserved',
        message: '[@wippy-fe/layout] capabilities.panelDrag is reserved for a future release. Set it to false or omit it.',
      }])
    }
    if (this.capabilities.tabs) {
      throw new LayoutValidationError([{
        kind: 'capability-reserved',
        message: '[@wippy-fe/layout] capabilities.tabs is reserved for a future release. Set it to false or omit it.',
      }])
    }

    assertValidLayout(declaration)
    this.decl = cloneLayout(declaration)
    // Hoist initial `modals` into the template registry. Boot state
    // = zero modals open. To open one, call `openModal(id)`. Each
    // template is shape-validated up-front so a malformed entry fails
    // at construction (clean stack trace) instead of silently sitting
    // in the registry until a coordinator tries to open it.
    if (this.decl.modals) {
      for (const [id, def] of Object.entries(this.decl.modals)) {
        assertValidModalDef(id, def)
        this.modalRegistry.set(id, def)
      }
      this.decl.modals = {}
    }
    this.emitter = createNanoEvents<LayoutEvents>()
  }

  // ────────────────────────────────────────────────────────────────
  // Full-declaration accessors
  // ────────────────────────────────────────────────────────────────

  /**
   * Returns a deep clone of the current declaration. Safe to mutate
   * by the caller (won't affect manager state).
   */
  getLayout(): LayoutDeclaration {
    return cloneLayout(this.decl)
  }

  /** Approved metadata for declared modal templates, including closed modals. */
  getRegisteredModals(): Array<{ id: string, title?: string }> {
    return [...this.modalRegistry].map(([id, definition]) => ({ id, ...(definition.title ? { title: definition.title } : {}) }))
  }

  /**
   * Replace the full declaration atomically. Validates + clones +
   * emits `change` once.
   */
  setLayout(next: LayoutDeclaration): void {
    assertValidLayout(next)
    this.decl = cloneLayout(next)
    this.emitChange()
  }

  /**
   * Active breakpoint name. Updated by the renderer via setActiveBreakpoint.
   */
  get activeBreakpoint(): string {
    return this._activeBreakpoint
  }

  /**
   * Set by the renderer when the container width crosses a threshold.
   * Emits `breakpoint` if the name changed.
   */
  setActiveBreakpoint(name: string, width: number): void {
    if (this._activeBreakpoint !== name) {
      this._activeBreakpoint = name
      this.emitter.emit('breakpoint', { name, width })
    }
  }

  // ────────────────────────────────────────────────────────────────
  // Panel mutations (affect all breakpoint layouts that reference the id)
  // ────────────────────────────────────────────────────────────────

  /**
   * Add a panel to the layout. Inserts into the `default` breakpoint at
   * the specified target. Other breakpoint layouts are untouched — if
   * a breakpoint should include the new panel, the consumer should
   * subsequently edit that breakpoint layout via setLayout.
   */
  addPanel(id: string, def: PanelDef, target: PanelTarget): void {
    if (this.decl.panels[id]) {
      throw new Error(`[@wippy-fe/layout] panel "${id}" already exists`)
    }
    const slot: PanelSlot = {
      panel: id,
      size: target.size ?? '1fr',
    }
    this.decl.panels[id] = def
    insertAtPosition(this.decl.layouts.default, slot, target)
    this.emitChange()
  }

  /**
   * Remove a panel from every breakpoint layout + from the panels map.
   */
  removePanel(id: string): void {
    if (!this.decl.panels[id]) {
      return // idempotent
    }
    for (const tree of Object.values(this.decl.layouts)) {
      if (tree)
        removeNode(tree, id)
    }
    delete this.decl.panels[id]
    this.emitChange()
  }

  /**
   * Patch a panel's PanelDef (component / props / title / icon).
   * Replaces fields listed in the patch; other fields preserved.
   */
  updatePanel(id: string, patch: Partial<PanelDef>): void {
    const existing = this.decl.panels[id]
    if (!existing) {
      throw new Error(`[@wippy-fe/layout] panel "${id}" not found`)
    }
    this.decl.panels[id] = { ...existing, ...patch }
    this.emitChange()
  }

  /**
   * Change a panel's `size` in the active breakpoint layout.
   * Other breakpoints are untouched.
   *
   * **Errors:** throws `LayoutValidationError` if `id` doesn't exist
   * in the panels map (programmer error). If `id` exists but isn't
   * present in the active breakpoint's layout tree, this is a no-op
   * (valid runtime state — the mutation will take effect when that
   * breakpoint becomes active).
   */
  resizePanel(id: string, size: SizeValue): void {
    if (!this.decl.panels[id]) {
      throw new LayoutValidationError([{
        kind: 'unknown-panel-id',
        message: `[@wippy-fe/layout] resizePanel: panel "${id}" does not exist`,
        panelId: id,
      }])
    }
    const tree = this.decl.layouts[this.getActiveLayoutName()]
    if (!tree)
      return
    const found = findSlotParent(tree, id)
    if (!found)
      return
    const slot = found.parent.children[found.index] as PanelSlot
    slot.size = size
    this.emitChange()
    this.emitter.emit('drag', {
      panel: id,
      delta: 0,
      direction: found.parent.direction,
    })
  }

  /**
   * Atomically resize two panels in the active breakpoint layout, emitting
   * a single `change` event for the pair. Used by paired splitter drag
   * (Phase 6) where one neighbor grows while the other shrinks in lockstep.
   *
   * Both panels must exist and (for the mutation to take effect) be present
   * in the active layout's tree. If either id is missing from the panels
   * map, throws `LayoutValidationError`. If either id exists but isn't in
   * the active tree, this is a no-op for that side (matching `resizePanel`'s
   * runtime contract). When both sides hit no-op, no `change` is emitted.
   *
   * The caller is responsible for ensuring `sizeAPx + sizeBPx` equals the
   * combined size of the two panels' previous total (a constant-sum invariant)
   * and that each value already respects the panels' `minSize` / `maxSize`.
   * The manager does NOT re-clamp here — clamping is the splitter's job at
   * pointermove time, where it has both sides' min/max in scope. Doing it
   * twice would double-clamp and cause off-by-one drift across rapid moves.
   *
   * Sizes are written as `${px}px` strings to match `resizePanel`'s storage
   * shape. Fractional inputs are rounded.
   */
  resizePanelPair(idA: string, sizeAPx: number, idB: string, sizeBPx: number): void {
    if (!this.decl.panels[idA]) {
      throw new LayoutValidationError([{
        kind: 'unknown-panel-id',
        message: `[@wippy-fe/layout] resizePanelPair: panel "${idA}" does not exist`,
        panelId: idA,
      }])
    }
    if (!this.decl.panels[idB]) {
      throw new LayoutValidationError([{
        kind: 'unknown-panel-id',
        message: `[@wippy-fe/layout] resizePanelPair: panel "${idB}" does not exist`,
        panelId: idB,
      }])
    }
    const tree = this.decl.layouts[this.getActiveLayoutName()]
    if (!tree)
      return
    const foundA = findSlotParent(tree, idA)
    const foundB = findSlotParent(tree, idB)
    // If neither side is in the active tree, nothing to do (no event).
    if (!foundA && !foundB)
      return

    let mutated = false
    let direction: 'horizontal' | 'vertical' | null = null
    if (foundA) {
      const slotA = foundA.parent.children[foundA.index] as PanelSlot
      slotA.size = `${Math.round(sizeAPx)}px`
      direction = foundA.parent.direction
      mutated = true
    }
    if (foundB) {
      const slotB = foundB.parent.children[foundB.index] as PanelSlot
      slotB.size = `${Math.round(sizeBPx)}px`
      direction = direction ?? foundB.parent.direction
      mutated = true
    }
    if (!mutated)
      return

    // Single coalesced `change` (emitChange microtask-coalesces anyway, but
    // we deliberately call it once to make the atomicity explicit).
    this.emitChange()
    // Single `drag` event for the pair — subscribers treat the pair as one
    // user-initiated gesture. `panel` is the A side (the one the splitter
    // considered "primary"); `delta` is 0 because the manager doesn't know
    // the previous size — same convention as `resizePanel`.
    if (direction) {
      this.emitter.emit('drag', {
        panel: idA,
        delta: 0,
        direction,
      })
    }
  }

  /**
   * Collapse a panel (sets `collapsed: true` on its slot in the active layout).
   * Throws if `id` is unknown; no-op if the panel's slot is not
   * `collapsible` or already in the desired state.
   */
  collapsePanel(id: string): void {
    this.setCollapsed(id, true, 'collapsePanel')
  }

  /**
   * Expand a collapsed panel. Same error contract as `collapsePanel`.
   */
  expandPanel(id: string): void {
    this.setCollapsed(id, false, 'expandPanel')
  }

  private setCollapsed(id: string, collapsed: boolean, methodName: string): void {
    if (!this.decl.panels[id]) {
      throw new LayoutValidationError([{
        kind: 'unknown-panel-id',
        message: `[@wippy-fe/layout] ${methodName}: panel "${id}" does not exist`,
        panelId: id,
      }])
    }
    const tree = this.decl.layouts[this.getActiveLayoutName()]
    if (!tree)
      return
    const found = findSlotParent(tree, id)
    if (!found)
      return
    const slot = found.parent.children[found.index] as PanelSlot
    if (!slot.collapsible)
      return
    if (slot.collapsed === collapsed)
      return
    slot.collapsed = collapsed
    this.emitChange()
  }

  /**
   * Move a panel to a new position within the active breakpoint layout.
   * Programmatic API — UI layer deferred to capabilities.panelDrag.
   *
   * Throws if `id` is unknown; no-op if the panel isn't in the active
   * breakpoint's tree.
   */
  movePanel(id: string, target: PanelTarget): void {
    if (!this.decl.panels[id]) {
      throw new LayoutValidationError([{
        kind: 'unknown-panel-id',
        message: `[@wippy-fe/layout] movePanel: panel "${id}" does not exist`,
        panelId: id,
      }])
    }
    const tree = this.decl.layouts[this.getActiveLayoutName()]
    if (!tree)
      return
    moveNode(tree, id, target)
    this.emitChange()
  }

  // ────────────────────────────────────────────────────────────────
  // Floating panels
  // ────────────────────────────────────────────────────────────────

  addFloating(id: string, def: FloatingPanelDef): void {
    if (!this.capabilities.floating) {
      throw new Error('[@wippy-fe/layout] capabilities.floating is disabled')
    }
    if (this.decl.floating?.[id]) {
      throw new LayoutValidationError([{
        kind: 'duplicate-floating-id',
        message: `[@wippy-fe/layout] addFloating: floating panel "${id}" already exists; call updateFloating to patch it or removeFloating first`,
      }])
    }
    this.decl.floating = this.decl.floating ?? {}
    this.decl.floating[id] = def
    this.emitChange()
  }

  removeFloating(id: string): void {
    if (!this.decl.floating?.[id])
      return
    delete this.decl.floating[id]
    this.emitChange()
  }

  updateFloating(id: string, patch: Partial<FloatingPanelDef>): void {
    const existing = this.decl.floating?.[id]
    if (!existing) {
      throw new Error(`[@wippy-fe/layout] floating panel "${id}" not found`)
    }
    this.decl.floating = this.decl.floating ?? {}
    this.decl.floating[id] = { ...existing, ...patch }
    this.emitChange()
  }

  // ────────────────────────────────────────────────────────────────
  // Drawer-mode panels
  // ────────────────────────────────────────────────────────────────

  /**
   * Open a panel's drawer overlay. Only meaningful when the panel's
   * active layout slot has `display: 'drawer-*'` — for inline slots,
   * the open state is set but has no visible effect (the renderer
   * ignores `drawerOpen` on inline slots).
   *
   * No-op if the panel id doesn't exist or if the drawer is already open.
   */
  openDrawer(id: string): void {
    this.setDrawerOpen(id, true, 'openDrawer')
  }

  /**
   * Close a panel's drawer overlay. Same contract as `openDrawer`.
   */
  closeDrawer(id: string): void {
    this.setDrawerOpen(id, false, 'closeDrawer')
  }

  /**
   * Flip a panel's drawer open state.
   */
  toggleDrawer(id: string): void {
    const existing = this.decl.panels[id]
    if (!existing) {
      throw new LayoutValidationError([{
        kind: 'unknown-panel-id',
        message: `[@wippy-fe/layout] toggleDrawer: panel "${id}" does not exist`,
        panelId: id,
      }])
    }
    this.setDrawerOpen(id, !existing.drawerOpen, 'toggleDrawer')
  }

  private setDrawerOpen(id: string, drawerOpen: boolean, methodName: string): void {
    const existing = this.decl.panels[id]
    if (!existing) {
      throw new LayoutValidationError([{
        kind: 'unknown-panel-id',
        message: `[@wippy-fe/layout] ${methodName}: panel "${id}" does not exist`,
        panelId: id,
      }])
    }
    if (existing.drawerOpen === drawerOpen)
      return
    this.decl.panels[id] = { ...existing, drawerOpen }
    this.emitChange()
  }

  // ────────────────────────────────────────────────────────────────
  // Modals
  // ────────────────────────────────────────────────────────────────

  /**
   * Open a modal. Two call shapes:
   *
   * 1. `openModal(id)` — open a pre-registered modal by id. The modal
   *    must have been declared in the initial layout's `modals` block
   *    or registered via `registerModal(id, def)`. Throws
   *    `LayoutValidationError(unknown-modal-id)` if no template exists.
   *
   * 2. `openModal(id, def)` — open with an explicit def, also registering
   *    it as a template so subsequent id-only opens reuse the same shape.
   *    Pre-existing template under the same id is replaced.
   *
   * Both shapes throw `LayoutValidationError(duplicate-modal-id)` when
   * the id is already open. Close it first, or pick a different id.
   */
  openModal(id: string, def?: ModalDef): void {
    if (!this.capabilities.modals) {
      throw new Error('[@wippy-fe/layout] capabilities.modals is disabled')
    }
    if (this.decl.modals?.[id]) {
      throw new LayoutValidationError([{
        kind: 'duplicate-modal-id',
        message: `[@wippy-fe/layout] openModal: modal "${id}" already open; close it first or use a different id`,
      }])
    }
    // Validate the new def BEFORE we touch the registry — a malformed
    // def must not corrupt a previously-good template under the same id.
    if (def)
      assertValidModalDef(id, def)
    const resolved = def ?? this.modalRegistry.get(id)
    if (!resolved) {
      throw new LayoutValidationError([{
        kind: 'unknown-modal-id',
        message: `[@wippy-fe/layout] openModal: no modal registered under "${id}". Pass a def or pre-register via the initial declaration's "modals" block / registerModal(id, def).`,
      }])
    }
    if (def)
      this.modalRegistry.set(id, def)
    this.decl.modals = this.decl.modals ?? {}
    this.decl.modals[id] = resolved
    this.emitChange()
  }

  /**
   * Pre-register a modal template. After this, `openModal(id)` (no def)
   * will use the registered shape. Re-registering an id replaces the
   * previous template; existing open modals are NOT affected (they
   * continue rendering with the def they were opened with).
   */
  registerModal(id: string, def: ModalDef): void {
    assertValidModalDef(id, def)
    this.modalRegistry.set(id, def)
  }

  closeModal(id: string): void {
    if (!this.decl.modals?.[id])
      return
    delete this.decl.modals[id]
    this.emitChange()
  }

  // ────────────────────────────────────────────────────────────────
  // Events
  // ────────────────────────────────────────────────────────────────

  on<K extends keyof LayoutEvents>(event: K, cb: LayoutEvents[K]): () => void {
    return this.emitter.on(event, cb)
  }

  /**
   * Fire a `change` event without mutating state. For host layers that
   * maintain their own side-state (e.g. live panel routes, sessionIds)
   * on top of the declaration and want `change` subscribers to re-emit
   * the snapshot after a side-state write. Microtask-coalesced like
   * every other mutation — safe to call in rapid bursts.
   */
  touch(): void {
    this.emitChange()
  }

  private emitChangeQueued = false
  private emitChange(): void {
    // Coalesce multiple synchronous mutations into one `change` event
    if (this.emitChangeQueued)
      return
    this.emitChangeQueued = true
    queueMicrotask(() => {
      this.emitChangeQueued = false
      this.emitter.emit('change', this.getLayout())
    })
  }

  // ────────────────────────────────────────────────────────────────
  // Internal helpers
  // ────────────────────────────────────────────────────────────────

  private getActiveLayoutName(): string {
    if (this.decl.layouts[this._activeBreakpoint]) {
      return this._activeBreakpoint
    }
    return 'default'
  }

  /**
   * Iterate over every slot in the active layout (for rendering/debug).
   */
  forEachActiveSlot(visitor: (slot: PanelSlot, parent: PanelTree) => void): void {
    const tree = this.decl.layouts[this.getActiveLayoutName()]
    if (!tree)
      return
    walkTree(tree, (slot, _path) => {
      // Walk up to find the direct parent (walkTree's path is by index — use findSlotParent)
      const found = findSlotParent(tree, slot.panel)
      if (found)
        visitor(slot, found.parent)
    })
  }
}
